window.NOTES = {"groups":["营养与消化基础","肠道与脑功能","营养素与补充剂"],"pages":[{"title":"脑营养的整体框架","subtitle":"从营养、免疫与代谢理解大脑的支持条件","core":["大脑依赖全身供氧、供能和营养支持；观察功能变化时，要同时看饮食、疾病和生活背景。","课程将营养分为宏量营养与微量营养，强调“吃进来”之后还要能够消化、吸收和利用。","补充效果需要明确目标和持续记录；个体经历可以提供线索，但不能直接证明普遍疗效。"],"cards_heading":"理解课程的三个出发点","cards":[{"title":"营养像工厂的原料","bullets":["<b>宏量营养<\/b>包括碳水化合物、蛋白质和脂肪，承担供能与组织构建等任务。","<b>微量营养<\/b>包括维生素和矿物质，参与酶反应、代谢调节与生命活动。","课堂用“有电但缺零件”比喻摄入能量充足、营养结构仍可能不完整。","体重、食量和主观精神状态都只是部分信息，不能单独判断具体缺哪种营养。"]},{"title":"局部表现与整体状态","bullets":["课程区分某项功能较弱与多项功能同时下降，提醒不要只盯住单个脑区。","感染、失血、睡眠不足或慢性疾病后出现变化，应记录时间关系和共同背景。","课堂将全局变化联系到营养、免疫和代谢，这是分析框架，不是排他诊断。","训练、饮食和疾病处理需要配合；补剂不能替代对持续恶化或新症状的检查。"]},{"title":"影响贯穿生命历程","bullets":["孕前与孕期关注叶酸、铁和整体营养，课程用神经发育说明早期准备的重要。","成长及成年阶段，饮食偏好、烟酒、睡眠、压力和环境暴露可能共同影响状态。","衰老阶段还要考虑疾病、药物和吸收能力变化，不能沿用年轻时的固定方案。","课程承认补剂不能保证预防肿瘤或神经退行性疾病，也不能一次解决终身问题。"]}],"table":{"title":"复习时把“感觉有效”拆开看","headers":["观察对象","可以记录","需要避免的推断"],"rows":[["症状与功能","疲劳、睡眠、训练耐受的变化","好转就证明某一种补剂有效"],["客观指标","适用的化验、体重与复查结果","疼痛减轻就等于骨密度改善"],["摄入与利用","食物结构、消化表现、用药情况","吃得多就一定吸收得多"],["时间与背景","开始日期、感染、作息和共同调整","把同时发生写成唯一因果"]]},"bottom_heading":"学习与记录要点","bottom":[{"title":"课程值得保留的提醒","bullets":["先写清想改善什么，再选择与问题相关的观察指标，减少不断加补剂的冲动。","个案前后照片和主观感受缺少对照，记录其启发，同时保留证据层级。","课堂承认知识会更新；后续复习应能回到原始说法和来源，而不是只记结论。"]},{"title":"具体内容需另行核对","bullets":["叶酸准备不应等到确认怀孕才开始；特殊高风险人群的用量需要单独评估。","原稿血铅数字未交代单位和检测条件，本笔记不将其改写成螯合治疗标准。","草药成分复杂不等于所有草药都有同一风险；鱼腥草“每口抽奖”等说法待核实。"]}],"caution":"原稿“所有人都缺营养”“全脑差必然是这三类原因”等表述过于绝对；本页保留整体评估思路，不保留这种诊断等号。","sources":["D1-1 00:00:00.770—01:05:24.320"],"number":2,"id":"topic-02","group":0,"references":[{"title":"FDA｜孕前及孕期饮食建议","url":"https://www.fda.gov/food/people-risk-foodborne-illness/dietary-advice-and-during-pregnancy","supports":"叶酸需在孕前及孕期考虑；不能等到确认怀孕才开始准备。"},{"title":"CDC｜儿童铅中毒检测","url":"https://www.cdc.gov/lead-prevention/testing/index.html","supports":"血铅参考值、检测与治疗阈值必须带单位，不能照抄原稿无单位数字。"}]},{"title":"脑肠联系与神经元支持","subtitle":"把内脏感觉、细胞代谢和训练反应放在一起理解","core":["课程用“氧气、养分、适宜刺激”概括神经元工作条件，强调训练之外的身体支持。","内脏感觉与自主神经活动参与消化调节，也与情绪和身体感受有关，联系是双向的。","训练效果短暂、没有改善或练后加重，都值得重新评估；这些现象本身不能诊断营养缺乏。"],"cards_heading":"从系统到细胞的三层观察","cards":[{"title":"内脏也在提供信息","bullets":["躯体感觉帮助识别手脚位置；内脏感觉则传递饥饿、饱胀及体内状态等信息。","课程介绍迷走神经、孤束核、岛叶和边缘系统，用来解释消化与情绪的联系。","胃肠蠕动、分泌和血流受到多种神经与激素信号调节，并非只由一个开关控制。","焦虑可以伴随胃肠不适，也可能反过来影响消化；不能把两者简化成单向因果。"]},{"title":"训练反应提供线索","bullets":["第一类是当场改善、回去后难以保持，应同时检查恢复、睡眠和整体健康状况。","第二类是与以往预期不同、训练缺少反应，应复核判断、目标及训练是否适合。","第三类是训练后症状加重或出现新问题，应降低负荷、停止不适刺激并查原因。","课堂把这些情况归入“神经元不稳定”，这是教学概括，不能替代具体临床评估。"]},{"title":"细胞层面的营养作用","bullets":["神经信号包含细胞内电活动和突触间化学传递，需要能量、递质和相关原料。","细胞膜不是静态外壳，受体、转运体和离子泵参与信息识别及内外环境维持。","微管、微丝构成细胞骨架；细胞内部运输和蛋白质合成都需要持续的代谢支持。","理解这些机制，是为了认识营养的作用位置，并不能直接推导某种补剂的剂量。"]}],"table":{"title":"三种常见训练反馈如何记录","headers":["课堂现象","记录重点","下一步思考"],"rows":[["当场好、次日回落","改善持续多久；睡眠和活动变化","训练剂量、恢复和疾病背景"],["训练后没有反应","是否重复出现；目标是否合适","评估准确性与方案适用性"],["练后更不舒服","何时开始；症状类型和严重度","停止诱发不适的操作并评估"],["缓慢出现改善","观察周期；同时改变的因素","区分趋势、波动与因果归因"]]},"bottom_heading":"理解机制，也保留观察边界","bottom":[{"title":"课堂的观察窗口","bullets":["讲师报告营养相关变化可能经历数周至数月；这是经验范围，不是统一疗程。","等待观察不能成为忽略副作用或推迟就医的理由，恶化与新症状需要及时处理。","短期测试成绩还受熟悉度、疲劳和练习影响，前后比较应尽量保持条件一致。"]},{"title":"复习时可问自己","bullets":["这次问题更像训练安排不合适，还是存在睡眠、疾病、摄入不足等共同背景？","记录里有哪些直接观察，哪些只是对机制的解释，两者是否已经混在一起？","能否用清楚的症状与时间记录说明变化，而不是只用“脑功能差”概括一切？"]}],"caution":"“便秘者因大脑感觉不到内脏而必然焦虑”“训练不佳就是缺氧或缺营养”均是课堂的过度概括，不作为诊断依据。","sources":["D1-1 01:06:12.160—01:39:13.050"],"number":3,"id":"topic-03","group":0,"references":[]},{"title":"消化从进食前开始","subtitle":"先梳理摄入、消化、吸收与利用，再讨论补充什么","core":["课程把“营养没效果”分为摄入不足、消化吸收受限及消耗增加，避免直接归咎于产品。","看到、闻到和想到食物可引起进食准备；食物入口后，咀嚼和唾液共同完成第一步处理。","咀嚼、口腔健康和吞咽能力决定进食是否顺利，后续胃肠问题不应忽略这一环。"],"cards_heading":"沿食物经过的过程理解","cards":[{"title":"吃进去之前的准备","bullets":["食物外观、气味和进食情境可引起唾液等头期反应，身体会预先准备消化。","反复在相同情境进食可能形成条件联结，课程用夜间美食视频说明这一点。","能引起预期反应，不等于观看视频本身必然造成胰岛素抵抗或消化系统损伤。","代糖种类、用量和饮食背景不同，不能仅用“欺骗大脑”判断其代谢结果。"]},{"title":"咀嚼与唾液的作用","bullets":["<b>机械处理<\/b>把大块食物变小，增加后续消化酶可接触的表面积，利于混合。","<b>唾液混合<\/b>帮助形成可吞咽的食团，并启动部分淀粉消化，保持口腔湿润。","唾液也含参与口腔防御的成分；口干、牙痛或牙周问题会进一步影响咀嚼。","咀嚼和口腔刺激参与神经反馈；课堂借三叉神经与脑干说明上下游的协调。"]},{"title":"营养为何没有转成效果","bullets":["吃得少或结构单一属于摄入问题，先查看日常饮食，而不是只看补剂种类。","饭后胀、长期腹泻或其他消化表现可能提示需要进一步评估，但不定位具体病因。","疾病和炎症可能改变营养需求；不能据此把所有补充剂都自行提高到大剂量。","即使成分相同，制剂形式、服用方法、耐受性和用药背景也可能影响实际结果。"]}],"table":{"title":"四个容易混淆的环节","headers":["环节","核心问题","课堂提示"],"rows":[["摄入","是否吃到足够且多样的食物","先看食物结构及进食能力"],["消化","能否把食物处理为可吸收成分","口腔、胃、胰腺和胆汁协同"],["吸收","消化产物能否通过肠道进入体内","消化完成仍不等于全部吸收"],["利用与消耗","能否用于代谢；需求是否变化","结合疾病、活动和营养状态"]]},"bottom_heading":"把基础环节落实到记录里","bottom":[{"title":"口腔与进食观察","bullets":["记录是否狼吞虎咽、口干、咀嚼疼痛或总依赖软食，必要时补充口腔检查。","比较进食前、进食中和饭后的症状，避免把所有不舒服都记成“胃不好”。","吞咽困难、喝水呛咳属于独立问题，不能靠增加咀嚼或自行训练替代评估。"]},{"title":"整理时的概念纠正","bullets":["人自身的消化酶不能分解所有膳食纤维；部分纤维主要由肠道菌群发酵。","唾液的保护作用不能简化成“蛋白酶把细菌融化”；舔唇加重也有多种原因。","常规营养支持首先服务于已有问题，不能因为了解更多机制就不断增加品种。"]}],"caution":"原稿将咀嚼不足直接推到广泛营养不良、菌群失调，并将观看食物视频与胰岛素抵抗相连；这些因果链需独立验证。","sources":["D1-1 01:39:13.050—02:04:09.280"],"number":4,"id":"topic-04","group":0,"references":[]},{"title":"嗅觉、记忆与进食","subtitle":"分清闻到、辨认和回忆，理解课堂嗅觉练习的目的","core":["食物风味由嗅觉与味觉共同形成；熟悉饮食可能掩盖嗅觉变化，不能仅凭“还能吃出味道”判断。","课堂嗅觉练习依次处理气味识别、名称联结与场景回忆，重点在观察不同能力。","闻错、叫错名称或前后测试波动不等于脑退化；持续嗅觉变化需要结合病史评估。"],"cards_heading":"嗅觉练习中的三个层次","cards":[{"title":"风味与嗅觉的入口","bullets":["鼻前嗅觉来自外部气味进入鼻腔；鼻后嗅觉来自进食时挥发物经咽部到达鼻腔。","味觉和两种嗅觉体验共同构成食物风味，鼻塞时食物“没味道”可由此理解。","嗅觉与记忆和情绪相关，熟悉气味可能唤起具体场景，而不仅是一个名称。","感染、鼻腔问题、头部外伤和年龄变化均可能影响嗅觉，原因不能一概而论。"]},{"title":"课堂的识别与联结","bullets":["示范使用丁香、柠檬、玫瑰和桉树，先了解学员是否接触过这些气味。","第一次不认识时告知名称，再随机呈现，观察能否将气味与名称对应。","答错后及时说明正确联结，避免连续更换气味使混淆叠加；记录表现而非贴标签。","名称记错与感知不到气味不是同一问题，文化经验及熟悉程度也会影响结果。"]},{"title":"从名称转向场景回忆","bullets":["识别相对稳定后，课堂进一步询问气味让人想起的事件、人物或地点。","比较练习前后的场景回忆表现，是课堂演示，结果也可能受重复测试影响。","课堂建议逐步扩大气味种类；若头晕、恶心或明显疲劳，应终止当次练习。","用香味配合学习属于课堂技巧，不能承诺改善考试成绩或治疗记忆障碍。"]}],"table":{"title":"观察结果不必急着归因","headers":["表现","可能涉及","记录方式"],"rows":[["能闻到却说不出名","经验不足或命名困难","描述气味；是否经提示可辨认"],["熟悉气味也分不清","嗅觉、注意或认知等因素","起病时间；鼻部症状和外伤史"],["做几轮后表现下降","适应、疲劳或测试波动","持续时间；不适；休息后变化"],["吃饭仍觉得有味道","味觉、鼻后嗅觉可能补偿","不能据此排除嗅觉改变"]]},"bottom_heading":"课堂补充方案与证据边界","bottom":[{"title":"原稿提及的营养成分","bullets":["维生素A被联系到嗅上皮，锌被联系到嗅觉信号，欧米伽3被联系到突触与炎症。","硫辛酸和牛磺酸也被提到，但课堂经验不足以证明适用于所有感染后嗅觉下降。","这些成分先作为课程索引保留；是否缺乏、是否适用和用量均需另行核实。"]},{"title":"嗅觉变化的实际影响","bullets":["除食欲和食物选择，还需关注是否察觉烟雾、燃气及变质食物等环境危险。","保留鼻炎、感染、头部外伤及药物变化的时间线，有助于后续查明原因。","嗅觉训练与记忆疾病治疗不是同一件事，不能凭一次练习宣布“康复完成”。"]}],"caution":"NIDCD将嗅觉障碍评估建立在病史、耳鼻喉检查与规范嗅觉测试上；原稿“四种气味辨认率”不属于痴呆诊断标准。","sources":["D1-1 02:04:09.280—02:45:07.460","D1-2 00:00:02.390—00:08:02.810"],"number":5,"id":"topic-05","group":0,"references":[{"title":"NIDCD｜嗅觉障碍","url":"https://www.nidcd.nih.gov/health/smell-disorders","supports":"嗅觉障碍原因、病史与耳鼻喉检查、规范嗅觉测试；四气味课堂练习不能诊断痴呆。"}]},{"title":"胃酸与胃食管反流","subtitle":"理解胃内消化，同时区分酸的多少与反流的机制","core":["胃酸有助于蛋白质初步消化、胃蛋白酶活化和防御部分病原体，但胃不是消化的终点。","胃内容物反到食管属于反流；出现酸味或烧心，不能据此判定胃酸过多或不足。","课堂重点提醒长期反流可能影响食管及口腔等部位；相关症状仍需排除其他原因。"],"cards_heading":"围绕胃酸的三组概念","cards":[{"title":"胃内消化怎样进行","bullets":["胃通过运动搅拌食物并与分泌物混合，逐步形成食糜，再分批排入十二指肠。","盐酸使蛋白质变性并帮助激活胃蛋白酶；蛋白质进一步分解仍需肠道消化过程。","胃酸参与食物中部分营养物质的释放，吸收情况还取决于食物形式及后续环节。","课堂反复强调消化能力，意在解释“吃肉很多仍可能营养不足”，不能反推所有人缺酸。"]},{"title":"反流关注屏障与动力","bullets":["食管下括约肌等构成抗反流屏障，屏障功能异常时胃内容物可进入食管。","食管对胃内容物的耐受与胃不同，反复暴露可能引起烧心、不适或黏膜损伤。","餐后、平卧、体重和解剖结构等背景都有价值，记录时不要只问是否尝到酸味。","原稿把屏障关闭主要归于酸浓度，进而推导“反酸就是缺酸”，这一结论不成立。"]},{"title":"食管外线索要鉴别","bullets":["声音嘶哑、咽部不适、慢性咳嗽和牙齿酸蚀可能与反流相关，也可能有别的病因。","清晨咳痰、夜间咳嗽或反复肺部问题不能单靠时间特征诊断，更不能排除吸烟危害。","牙齿广泛损伤应由口腔检查区分龋齿、酸蚀和牙周问题，不能一律归因于反流。","长期反流可出现并发症；持续吞咽困难、明显消瘦或出血不能靠补剂试验等待。"]}],"table":{"title":"课堂判断与规范理解对照","headers":["课堂表述","整理后的理解","不宜直接照做"],"rows":[["反酸是胃酸不足的表现","反流症状不能测定酸分泌量","自行用酸性物质试诊"],["抑酸药会使问题恶化","适当抑酸是GERD常用治疗","因课堂说法自行停PPI"],["早晨咳痰要查反流","反流只是需要鉴别的因素之一","忽略肺部与耳鼻喉问题"],["满口坏牙提示反流","酸蚀可提供线索但不是确诊","用敲牙或漱口替代检查"]]},"bottom_heading":"复习时分开记录症状与解释","bottom":[{"title":"有用的症状时间线","bullets":["记录烧心、反流、餐后胀满是否同时出现，以及与平卧、餐量和食物的关系。","补充正在使用的药物、既往胃镜结果和治疗反应，避免把处方药与随意用药混谈。","发生黑便、呕血、持续剧痛或吞咽困难时，优先处理警示症状而非调整补剂。"]},{"title":"长期后果如何理解","bullets":["巴雷特食管涉及食管上皮变化，需要规范诊断和随访，不能靠症状自行判断。","反流并不意味着必然发生巴雷特食管或癌变；风险判断应结合具体检查。","处理的目标包括减轻症状、保护食管和识别并发症，不能只围绕“增加胃酸”。"]}],"caution":"NIDDK明确PPI可有效治疗GERD并帮助食管愈合；原稿“一律补胃酸、不要抑酸”不能作为停药或饮醋治疗依据。","sources":["D1-2 00:08:02.810—00:26:00.400","D1-2 00:30:52.950—00:59:08.160","D1-2 02:13:11.520—02:19:11.400"],"number":6,"id":"topic-06","group":0,"references":[{"title":"NIDDK｜成人GER与GERD","url":"https://www.niddk.nih.gov/health-information/digestive-diseases/acid-reflux-ger-gerd-adults","supports":"反流的定义及食管下括约肌功能；不能从酸味推断胃酸分泌量。"},{"title":"NIDDK｜GER与GERD的治疗","url":"https://www.niddk.nih.gov/health-information/digestive-diseases/acid-reflux-ger-gerd-adults/treatment","supports":"PPI是有效的GERD治疗，能帮助食管愈合；不支持一律停抑酸药并补酸。"}]},{"title":"胃黏膜与消化支持方案","subtitle":"把课堂提出的方法与溃疡、感染的规范处理区分开","core":["胃黏膜屏障能保护胃壁，幽门螺杆菌感染及某些药物等可破坏防御，造成消化性溃疡。","原稿强调感染处理与短期支持，但其补酸、咽喉漱口等方法不能替代明确病因与治疗。","胃溃疡、十二指肠溃疡和胃食管反流不是同一个问题，不应套用同一补剂方案。"],"cards_heading":"先分清问题，再看课堂方法","cards":[{"title":"黏膜保护与溃疡","bullets":["课程用胃壁外的保护层解释“胃内有酸却通常不自我消化”，有助于理解屏障概念。","幽门螺杆菌是消化性溃疡的重要病因，但原稿“无菌无溃疡”随后也被课堂提问修正。","非甾体抗炎药也是常见病因，应记录阿司匹林、布洛芬等药物，而非只问感染。","严重疾病相关应激、其他疾病或少见病因也可能参与，症状不足以自行区分。"]},{"title":"幽门螺杆菌如何处理","bullets":["原稿提醒感染与溃疡、胃癌风险相关，值得认真检查和按适应证处理。","根除治疗需考虑药物过敏、既往抗生素使用及耐药情况，不能随意拼药。","现代根除方案包含抑酸治疗；原稿建议自行删去PPI，与规范方案不一致。","完成疗程后还需按要求确认根除，症状减轻并不能证明细菌已经清除。"]},{"title":"原稿提出的短期支持","bullets":["课堂提出苹果醋和盐酸甜菜碱来支持胃内酸度，但未提供足以普遍推广的临床证据。","盐酸甜菜碱不同于甜菜根粉；原稿“氯酸根形成胃酸”存在化学概念错误。","课堂提出咽喉漱口刺激迷走神经，属于其训练思路，不能保证恢复胃酸分泌。","吞咽困难、反复呛咳者不能照搬咽喉含水训练，更不应追求完成固定时长。"]}],"table":{"title":"原稿方法保留为学习索引","headers":["课堂提及","预期目的","本笔记的边界"],"rows":[["咽喉漱口","训练咽喉并影响自主神经","不写作已证实的低胃酸疗法"],["苹果醋／盐酸甜菜碱","短期改变胃内酸度","不用于自行诊断或治疗反流"],["抗生素与铋剂","处理幽门螺杆菌","由完整根除方案决定组合"],["全谱消化酶／胆盐","支持后续消化","先确认问题；并非人人适用"]]},"bottom_heading":"把风险点放在具体操作旁","bottom":[{"title":"补酸不能从症状倒推","bullets":["反酸、烧心、胀满都可能有不同原因，未经评估不能断言“缺多少酸”。","原稿提到直接喝醋酸，不应照做；酸性物质可能损伤牙齿和食管，溃疡更需谨慎。","胃镜、感染检测与必要的功能检查回答的问题不同，不能用一次试吃代替。"]},{"title":"不混淆治疗与自我尝试","bullets":["不要因担心长期用药就自行终止有明确适应证的处方，应讨论疗程和复评。","呕血、黑便、持续严重腹痛等可能提示并发症，需要及时医疗处理。","课堂方法的记录价值在于保存思路，应用之前仍要确认对象、证据和禁忌。"]}],"caution":"NIDDK列出幽门螺杆菌及NSAIDs等多种溃疡病因；ACG根除方案包含抑酸治疗，因此“无菌无溃疡”和自行去PPI均不可照搬。","sources":["D1-2 00:26:00.400—00:30:52.950","D1-2 00:59:08.160—01:04:43.600","D1-2 02:19:11.400—02:34:36.720"],"number":7,"id":"topic-07","group":0,"references":[{"title":"NIDDK｜消化性溃疡的症状与病因","url":"https://www.niddk.nih.gov/health-information/digestive-diseases/peptic-ulcers-stomach-ulcers/symptoms-causes","supports":"幽门螺杆菌、NSAIDs及其他原因；黑便、呕血、剧痛等警示症状。"},{"title":"ACG｜2024幽门螺杆菌治疗指南摘要","url":"https://webfiles.gi.org/links/journals/ACG-Hpylori-Guidelines-Highlights-2024-FINAL.pdf","supports":"根除方案含抑酸药；应按规范确认根除，不自行删去PPI。此为成人指南，不直接推至儿童。"}]},{"title":"胰腺、胆汁与脂肪吸收","subtitle":"理解十二指肠的协作，不用单个症状判断分泌是否不足","core":["食糜进入十二指肠后，胰液、胆汁与肠道共同参与后续消化，食物随后才能被吸收。","胆汁参与脂肪处理，脂肪吸收异常可能影响脂溶性维生素，但不能仅凭打嗝作判断。","课程反对因怕血脂就完全去掉脂肪；饮食调整仍须同时考虑脂肪类型、总量和整体结构。"],"cards_heading":"三项相互配合的工作","cards":[{"title":"胰液继续完成消化","bullets":["胰腺提供蛋白酶、脂肪酶和淀粉酶等，处理不同食物成分，作用不能互相替代。","胰液中的碳酸氢盐有助于中和进入十二指肠的酸，为后续消化提供合适环境。","酸性食糜及营养物质能引起不同的神经、激素反应，不能只用“酸开关”解释。","原稿把十二指肠溃疡统一归因于胃酸不足，属于未经支持的简化，不能据此补酸。"]},{"title":"胆汁帮助处理脂肪","bullets":["胆汁由肝脏产生，经胆道输送，胆囊参与储存和释放，不能把全部功能归给胆囊。","胆盐参与脂肪乳化和胶束形成，便于消化产物及脂溶性维生素的吸收。","A、D、E、K属于脂溶性维生素，疑有脂肪吸收问题时，需要整体营养评估。","课程提及油腻后胀满、鱼油后打嗝等线索，但这些表现并非胆汁不足的特异标志。"]},{"title":"脂肪与血脂的讨论","bullets":["课堂提醒，限制脂肪后若用大量精制碳水替代，饮食结构未必真正改善。","学员举餐后血浆脂肪增多反例，讨论最后落在“要适量摄入，而非越多越好”。","空腹血脂与餐后脂质变化回答的问题不同，不能拿一次进食后的现象替代整体评估。","不把“胆盐不足”作为所有便秘或高血脂的共同解释，也不把肥肉当作降脂方法。"]}],"table":{"title":"消化支持中需要分开的对象","headers":["对象","主要任务","不能直接推出"],"rows":[["胰酶","分解蛋白质、脂肪和淀粉","胀气就应补全谱消化酶"],["碳酸氢盐","参与中和胃内来的酸","十二指肠溃疡一定缺胃酸"],["胆盐","帮助脂肪及相关成分吸收","鱼腥味打嗝就是胆汁不足"],["小肠黏膜","吸收消化产物","消化完成等于营养全部吸收"]]},"bottom_heading":"课堂补充方案怎样保留","bottom":[{"title":"外源补充的适用性","bullets":["原稿把消化酶、胆盐定位为短期帮助，并强调仍要处理消化系统的基础问题。","确诊胰腺外分泌功能不全者可能需要持续胰酶治疗，不能套用“超过三月停用”。","部分酶制剂有特殊释放结构，是否能掰开或混食必须按具体说明与专业指导。"]},{"title":"观察要连成完整记录","bullets":["记录食物类型、饭后症状、大便变化及体重趋势，比只记“怕油”更有意义。","长期腹泻、脂肪便或体重下降需要查明原因，儿童还应关注生长情况。","补脂溶性维生素时既要考虑吸收，也要避免重复摄入；“吸收差”不等于可任意加量。"]}],"caution":"原稿“消化酶用满三个月会导致胰腺萎缩”不能作为停药规则；AGA对确诊胰腺外分泌功能不全的治疗包括胰酶替代。","sources":["D1-2 01:04:43.600—01:20:43.960","D1-2 02:29:39.510—02:34:36.720"],"number":8,"id":"topic-08","group":0,"references":[{"title":"AGA｜胰腺外分泌功能不全","url":"https://patient.gastro.org/exocrine-pancreatic-insufficiency/","supports":"EPI可表现为消化吸收问题，治疗包括胰酶替代；无一律使用三个月就停的规则。"}]},{"title":"肝脏功能与体征观察","subtitle":"肝脏参与代谢与转化，但肤色比较不能替代检查","core":["课程把肝脏放在消化吸收后的代谢环节，强调糖原储存、物质转化、激素代谢与凝血相关功能。","观察皮肤和眼部变化有助于发现问题，但黄、暗、斑或蜘蛛痣都需要结合病史和检查解释。","“支持肝功能”应先明确病因与目标，不能用外观改善证明解毒能力恢复，也不能以补剂替代诊疗。"],"cards_heading":"肝脏这一环如何理解","cards":[{"title":"功能不止于“解毒”","bullets":["肝脏参与营养加工、储存和分配，也合成多种蛋白质及处理部分代谢产物。","药物和外来化学物的代谢可能涉及转化与结合，并经胆汁或尿液等途径排出。","课程用“脂溶性变为水溶性”帮助理解部分过程，不能把所有物质都套入同一模型。","所谓一期、二期代谢并不是简单先危险、后安全的两步，不等于补某成分就能包办。"]},{"title":"影响肝脏的背景","bullets":["酒精、某些药物、草药与职业暴露是原稿反复提示的因素，应记录具体产品和时间。","饮食结构和代谢状态同样重要，但不能将肝脏问题全部归结为吃糖。","所谓天然、保健或营养成分也可能产生不良作用，产品组合及用量需要完整列出。","持续异常应查病因，单次转氨酶正常既不证明一切正常，也不能反过来否定检验价值。"]},{"title":"外观线索如何解释","bullets":["明显皮肤或眼白黄染可提示胆红素相关问题；还需区分产生、肝脏处理和排泄环节。","蜘蛛痣具有中心及向外辐射的血管形态，原稿特意与单个红点样血管瘤区分。","蜘蛛痣也可在特定生理状态出现，不能见到一个就断言已发生严重肝病。","将手心手背与他人比较是课堂观察活动；光线、肤色和色素差异使其不能用于诊断。"]}],"table":{"title":"外观表现与下一步信息","headers":["观察线索","补充了解","避免的等号"],"rows":[["皮肤较黄","眼白、尿色、饮食和出现时间","比别人黄＝肝解毒差"],["面部发暗或色斑","日晒、激素变化、皮肤病史","长斑＝胆红素沉积"],["蜘蛛痣样血管","数量变化、妊娠及其他体征","出现一处＝严重肝损伤"],["容易出血或淤青","药物、血液及凝血相关检查","凝血异常＝某一种补剂不足"]]},"bottom_heading":"课堂保肝组合的记录方式","bottom":[{"title":"原稿提及的组成","bullets":["谷胱甘肽、水飞蓟和五味子被讲师列为主要组合，NAC、锌等被放在辅助位置。","这些名称保留为课程内容索引，不将“最强恢复剂”作为已验证疗效或个人处方。","水飞蓟被联系到肝细胞保护，五味子被联系到纤维化；人体疗效仍需具体证据。"]},{"title":"判断效果需要对准问题","bullets":["皮肤颜色、疲劳与化验结果属于不同指标，不能只凭其中一个宣布肝功能恢复。","既有肝病或正在用药者，增加草药和补剂前须检查相互作用及肝损伤风险。","原稿关于枸杞原浆与肝损伤的报道未给来源，不能扩写成所有原浆有毒或枸杞绝对安全。"]}],"caution":"NCCIH认为水飞蓟用于肝病的临床证据仍不足或不一致；肤色比较、“最强保肝组合”及任意加量不能写成可靠诊疗规则。","sources":["D1-2 01:20:43.960—01:45:22.920","D1-2 02:34:36.720—02:41:45.600"],"number":9,"id":"topic-09","group":0,"references":[{"title":"NCCIH｜水飞蓟的证据与安全性","url":"https://www.nccih.nih.gov/health/milk-thistle","supports":"肝病临床试验证据不一致或不足，不能称通用最强保肝组合。"},{"title":"NCBI MeSH｜二期代谢解毒","url":"https://www.ncbi.nlm.nih.gov/mesh/68050217","supports":"谷胱甘肽结合属于二期代谢过程，原稿将其主要归于一期解毒不准确。"}]},{"title":"皮肤、抗氧化与补剂索引","subtitle":"保留课堂的分组思路，同时核对剂量和疗效边界","core":["课堂将痤疮、色素沉着、湿疹和皮肤老化分别讨论，提醒表面相似不等于同一种问题。","谷胱甘肽、NAC、维生素C等被联系到抗氧化；生化作用不能直接等同于口服后的治疗效果。","高剂量维生素及多种补剂叠加有风险，水溶性不代表无限安全，维生素D也会中毒。"],"cards_heading":"课堂组合背后的分类逻辑","cards":[{"title":"抗氧化概念","bullets":["课程将自由基与氧化压力联系到细胞损伤，强调抗氧化物质参与身体防御。","谷胱甘肽与NAC在原稿中分别被介绍为直接支持及合成相关原料，不能据此比较临床优劣。","原稿将谷胱甘肽的作用归于肝脏“一期解毒”，这一阶段划分不准确，应单独核对。","药物注射用途、实验室发现和口服保健品效果属于不同证据，不能互相直接替代。"]},{"title":"皮肤问题需要分开看","bullets":["痤疮伴红肿、色斑、湿疹瘙痒和皮肤松弛的表现不同，观察时应分别描述。","日晒、激素、皮肤屏障、遗传和疾病等都可能参与，不能全部解释为肝脏解毒差。","原稿区分烟酸与烟酰胺，并提醒烟酸可能潮红；两者也不能因此随意互换大剂量。","原稿提到DIM影响激素相关途径，但缺少适应证和安全条件，不能作为自行调激素方案。"]},{"title":"剂量不能从经验照搬","bullets":["维生素C有吸收比例与剂量关系，原稿“量大就行”的个人体验不是安全证明。","维生素D过量可引起高钙血症等毒性，原稿“少有不会中毒”这一判断需要纠正。","成人维生素D常规可耐受最高摄入量为每日4000 IU；治疗性用量需专业监测。","NIH列出的成人维生素C上限为每日2000毫克，儿童上限更低，不按成人经验推算。"]}],"table":{"title":"仅作为课堂内容索引的四组方案","headers":["课堂关注","原稿明确提及","需要核实"],"rows":[["痤疮并关注肝脏","谷胱甘肽／NAC、水飞蓟","病因、临床疗效与用药风险"],["发黄、发暗、长斑","还原型谷胱甘肽、维C、烟酰胺","色斑诊断；不能以美白代替治疗"],["湿疹及过敏表现","维D，问答提及EPA、槲皮素","剂量与完整组合未充分明确"],["松弛、皱纹","辅酶Q10及“心肌肽”","“心肌肽”为转写名，待听原音"]]},"bottom_heading":"复习时保留哪些信息","bottom":[{"title":"保留分类，不抄成处方","bullets":["记录讲师为何区分这些问题，而不是把每组名称直接转换成一张购买清单。","资料没有显示的课件成分不补写；转写不清楚的名称保留疑点，不猜成另一产品。","原稿称Q10不同形式没有差别，需结合制剂与研究核对，不能扩成适用于所有产品。"]},{"title":"把儿童与成人分开","bullets":["儿童维生素D剂量必须按年龄、摄入来源及医疗评估决定，不能照搬课堂大剂量。","高剂量或长期方案要看总摄入、药物相互作用和监测，不能只问“有没有感觉”。","皮肤疾病持续或加重应明确诊断；不能在等待补剂效果的数月里忽略其他治疗。"]}],"caution":"原稿维生素D出现“毫克／单位”混写，并给出明显超出常规上限的成人与儿童用量；本页仅保留经NIH核对的上限，不作补充剂量。","sources":["D1-2 01:45:22.920—02:03:31.040"],"number":10,"id":"topic-10","group":0,"references":[{"title":"NIH ODS｜维生素D专业资料","url":"https://ods.od.nih.gov/factsheets/VitaminD-HealthProfessional/","supports":"维生素D过量可中毒；成人常规UL为每日4000 IU，儿童随年龄不同，UL不是补充建议。"},{"title":"NIH ODS｜维生素C专业资料","url":"https://ods.od.nih.gov/factsheets/VitaminC-HealthProfessional/","supports":"成人总摄入UL为每日2000毫克，儿童上限更低；大剂量有不良反应，UL不是补充建议。"},{"title":"NCBI MeSH｜二期代谢解毒","url":"https://www.ncbi.nlm.nih.gov/mesh/68050217","supports":"谷胱甘肽结合属于二期代谢过程，原稿将其主要归于一期解毒不准确。"}]},{"title":"菌群、纤维与大便观察","subtitle":"把肠道当作生态系统，区分观察线索与疾病诊断","core":["课程关注菌群代谢物与脑肠联系，主张重视饮食和肠道环境，而非只追求增加益生菌种类。","可溶性与不可溶性纤维作用有所不同；菊粉能被发酵，也可能引起气体和不耐受。","便形、腹胀与饮食反应有记录价值，但不能据此确诊菌群失调、炎症或小肠细菌过度生长。"],"cards_heading":"理解菌群的三个层面","cards":[{"title":"大肠与菌群代谢","bullets":["大肠参与水分处理和粪便形成，菌群可利用部分未被宿主消化的食物成分。","课堂介绍发酵、短链脂肪酸及色氨酸相关途径，以说明菌群与宿主的相互作用。","这些机制线索不等于能从肠道症状推断脑内递质不足，更不能保证补菌改善睡眠。","食物、抗生素、疾病与个体差异均会影响菌群；单一产品难以概括整个生态。"]},{"title":"纤维与益生菌","bullets":["不可溶性纤维与粪便体积及排便过程相关；部分可溶性纤维可被菌群发酵。","菊粉是原稿强调的可发酵纤维，优点是方便获得，但耐受性和需求存在差异。","原稿认为益生菌受储存、存活和菌株等条件影响，成本与效果都值得比较。","不能把“多菌种、轮换吃”写成普遍规则，益生菌的作用需看菌株和具体用途。"]},{"title":"小肠细菌过度生长","bullets":["小肠和大肠的菌群环境不同；SIBO指小肠异常增多的细菌与相关症状问题。","课堂用“提前收过路费”比喻细菌竞争营养并发酵，可能出现胀气及吸收障碍。","菊粉后腹胀也可能属于正常发酵、剂量问题或其他不耐受，不能当作诊断试验。","持续症状需要结合病史及必要检测；ACG介绍的常用评估包括规范呼气试验。"]}],"table":{"title":"布里斯托便形用于描述，不单独判病因","headers":["类型","外观概括","可记录的意义"],"rows":[["1—2型","颗粒状或结块偏硬","偏干；结合排便困难和频率"],["3—4型","成形的条状便","常见的较理想形态"],["5型","较软、边界清楚的小块","结合饮食、频率与个人基线"],["6—7型","糊状或水样","记录持续时间、脱水及伴随症状"]]},"bottom_heading":"观察与调整怎样更有用","bottom":[{"title":"记录完整的排便情况","bullets":["便形之外还需记录次数、费力、急迫、疼痛、血液和夜间症状，避免只盯一张量表。","长期不成形或便秘可能有多种原因，不能分别等同于缺纤维和好细菌太少。","水样便不一定是炎症，便秘也可能伴稀便；变化明显或持续应进一步查明。"]},{"title":"课堂建议的保留与修正","bullets":["原稿强调不要滥用抗生素，同时明确“该用就用”，不能把抗生素一概排斥。","增加纤维应关注耐受和饮水；若症状明显加重，不能以“菌群正在打仗”解释后硬撑。","原稿链球菌与念珠菌名称混用，白厚舌苔不能单独证明念珠菌或肠道感染。"]}],"caution":"ACG要求症状结合小肠细菌增多的证据来评估SIBO；“吃菊粉胀气就确诊”及仅凭便形推断炎症或菌群比例均不成立。","sources":["D1-2 02:03:31.040—02:14:33.610","D1-2 02:41:45.600—02:59:49.120"],"number":11,"id":"topic-11","group":0,"references":[{"title":"ACG｜小肠细菌过度生长","url":"https://gi.org/topics/small-intestinal-bacterial-overgrowth-sibo/","supports":"SIBO需结合症状和细菌增多证据，常用规范呼气试验；菊粉反应不能确诊。"}]},{"title":"小肠菌群与菊粉耐受","subtitle":"把补充后的反应、消化基础与疾病诊断分开看","core":["小肠细菌过度生长（SIBO）可伴腹胀、腹痛、腹泻及营养吸收问题，需要结合病史与检查判断。","菊粉属于可发酵膳食纤维；吃后产气增多提示需要关注耐受，但单凭这一反应不能确诊 SIBO。","课堂主线是先看消化与肠道环境，再讨论菌群；具体抗菌治疗不能直接照搬课堂经验。"],"cards_heading":"课堂提出的三个观察层次","cards":[{"title":"发酵与吸收","bullets":["<b>位置有区别：<\/b>小肠承担大量营养吸收，菌群在这里异常增多时，可能干扰食物处理与吸收。","<b>短链脂肪酸：<\/b>课堂提到乙酸、丙酸和丁酸；不能把某一种物质简单分成绝对有益或有害。","<b>营养被利用：<\/b>讲师用“收过路费”比喻细菌消耗营养，帮助理解部分营养缺乏的可能来源。","<b>概念要分清：<\/b>原稿同时讨论念珠菌；它属于真菌，不能直接与小肠细菌过度生长画等号。"]},{"title":"补充后的反应","bullets":["<b>先看胃肠：<\/b>留意腹鸣、腹胀、排气、食欲与排便变化，记录是否紧接着补充菊粉出现。","<b>儿童表达有限：<\/b>不会描述腹胀时，可能先表现为拒食或不愿继续吃；应结合其他表现判断。","<b>行为变化：<\/b>烦躁、语言或社交变化是课堂观察，原因很多，不能据此认定丙酸中毒。","<b>关注变化条件：<\/b>剂量、同时吃了什么、原有疾病与其他补剂，都可能影响一次观察的结果。"]},{"title":"处理思路","bullets":["<b>课堂两条路径：<\/b>一是调整纤维补充量与耐受，二是讨论针对微生物的处理，二者目的不同。","<b>基础因素：<\/b>讲师反复强调胃酸、消化酶与饮食；实际评估还需要关注动力和既往病史。","<b>复发问题：<\/b>症状暂时改善不等于原因消失，后续仍要观察饮食、排便和营养状态。","<b>治疗依据：<\/b>AGA 强调查找基础原因、纠正营养缺乏与适当治疗，不能只凭一组症状选药。"]}],"table":{"title":"课堂提到的物质：名称与讨论边界","headers":["物质","课堂讨论","复习时保留的限定"],"rows":[["菊粉","作为菌群可利用的纤维","耐受差不等于确诊；先记录变化"],["盐酸小檗碱","讲师的抗菌使用经验","剂量前后不一致，不能整理成统一处方"],["生蒜","讨论大蒜素及所含纤维","食材作用不等于已证实的 SIBO 治疗"],["肉桂","课堂认为作用较温和","食品与药物作用不能直接替代"]]},"bottom_heading":"复习时抓住什么","bottom":[{"title":"把观察写具体","bullets":["写明开始补充的时间、产品、份量和原有症状。","分开记录胃肠反应与行为变化，避免用一个词概括全部。","持续腹痛、腹泻或生长受影响时，需要进一步医学评估。"]},{"title":"不要混淆的三件事","bullets":["纤维不耐受、小肠细菌过度生长和食物过敏不是同一概念。","讲师关于发育迟缓与丙酸的解释属于课堂推断，不能作为诊断链。","NCCIH 提醒小檗碱不用于婴儿、孕期及哺乳期，且可能与药物相互作用。"]}],"caution":"原稿“没有抗药性”“儿童减半用”及睡前效果最佳均未提供足够证据，未作为执行建议收录。","sources":["D1-3 00:00:04—00:19:21","D2-1 00:58:22—00:59:27"],"number":12,"id":"topic-12","group":1,"references":[{"id":"P2-R1","title":"AGA：Diagnosis and management of SIBO","url":"https://gastro.org/clinical-guidance/diagnosis-and-management-of-small-intestinal-bacterial-overgrowth-sibo/","supports":"SIBO症状、诊断局限及处理基础病因与营养缺乏的框架"},{"id":"P2-R2","title":"NCCIH：Diabetes and Dietary Supplements","url":"https://www.nccih.nih.gov/health/diabetes-and-dietary-supplements-what-you-need-to-know","supports":"小檗碱不用于婴儿、孕期、哺乳期及药物相互作用风险"}]},{"title":"肠屏障与营养支持","subtitle":"理解通透性、免疫反应与课堂提出的支持思路","core":["课堂所说“肠漏”主要指肠屏障与通透性的变化，不是肠道真的穿了一个洞。","营养吸收、屏障完整性、免疫反应是不同环节；能消化食物，不代表其他环节一定正常。","谷氨酰胺、EPA、姜黄素和维生素 D 是讲师提出的组合，不能据此视为已确立的通用修复方案。"],"cards_heading":"先理解机制，再看组合","cards":[{"title":"屏障在做什么","bullets":["<b>正常边界：<\/b>肠上皮与细胞间连接参与屏障功能，控制肠腔内容物与机体内部的接触。","<b>课堂比喻：<\/b>讲师用细胞间“扣子松开”描述通透性改变；真实结构比绒毛间距更复杂。","<b>可能影响：<\/b>课堂从异常接触谈到免疫激活、炎症与食物反应，这些联系不能一概推为因果。","<b>概念边界：<\/b>“肠漏综合征”不能替代具体疾病诊断，也不能用来解释所有过敏或不适。"]},{"title":"寻找影响因素","bullets":["<b>课堂列举：<\/b>饮酒、压力、感染、脑外伤及特定食物反应，是讲师讨论的影响线索。","<b>区分层次：<\/b>动物实验、机制推测与人体临床结果的证据强度不同，不能直接互相替代。","<b>食物反应：<\/b>麸质和茄科食物在课中被提到；需要个体证据，不支持所有人统一戒除。","<b>甲状腺插曲：<\/b>结节、抗体升高与功能异常是不同信息，不能只看抗体而忽略甲状腺功能。"]},{"title":"课堂支持思路","bullets":["<b>供能：<\/b>讲师以谷氨酰胺说明肠道细胞需要能量与原料，不是把补剂直接“贴”在屏障上。","<b>炎症与免疫：<\/b>EPA、姜黄素、维生素 D 分别被放进脂肪、炎症及免疫调节的讨论。","<b>区域差异：<\/b>丁酸被着重放在大肠细胞供能部分，课堂未把它列为人人必需的成分。","<b>微量元素：<\/b>锌只是补充讨论；长期过量可能干扰铜代谢，不能用越多越好理解。"]}],"table":{"title":"课堂组合的用途定位","headers":["成分","课堂侧重点","整理时的边界"],"rows":[["谷氨酰胺","肠道细胞的能量与原料","不同疾病与营养状态不能一概而论"],["EPA","脂肪组成与炎症讨论","区分 EPA 含量和鱼油总重量"],["姜黄素","课堂强调抗炎与利用度","含量、制剂和安全性都要看"],["维生素 D","免疫调节与抗菌肽","课堂高剂量不能当作日常补充量"],["丁酸、锌","按具体问题补充讨论","不是固定组合中必须叠加的项目"]]},"bottom_heading":"标签与条件，不能省略","bottom":[{"title":"看清产品标签","bullets":["姜黄粉、提取物和实际姜黄素含量不是同一个数。","比较每份含量、每份粒数与剂型，不能仅看瓶身大字。","“吸收更高”不等于更安全；NCCIH 提醒部分高利用度制剂存在肝损伤风险。"]},{"title":"把核查补充记在旁边","bullets":["成人维生素 D 一般可耐受最高摄入量为每日 4000 IU；医学治疗须另行评估。","怀疑乳糜泻时，不宜在完成检查前自行开始无麸质饮食。","原稿未提供完整临床依据，四种成分同时使用的收益也不能由机制直接证明。"]}],"caution":"本页保留课堂组合用于理解课程；具体疾病、补充剂量和疗程需分别判断，不能用“肠漏”统一处理。","sources":["D1-3 00:19:21—00:31:37","D1-3 00:40:41—00:58:25"],"number":13,"id":"topic-13","group":1,"references":[{"title":"NIH ODS｜维生素D专业资料","url":"https://ods.od.nih.gov/factsheets/VitaminD-HealthProfessional/","supports":"维生素D过量可中毒；成人常规UL为每日4000 IU，儿童随年龄不同，UL不是补充建议。"},{"id":"P2-R4","title":"NCCIH：Turmeric: Usefulness and Safety","url":"https://www.nccih.nih.gov/health/turmeric","supports":"姜黄素制剂差异、疗效证据局限及高利用度产品的肝损伤风险"},{"id":"P2-R5","title":"NIDDK：Diagnosis of Celiac Disease","url":"https://www.niddk.nih.gov/health-information/digestive-diseases/celiac-disease/diagnosis","supports":"怀疑乳糜泻不宜在检查前自行无麸质饮食"}]},{"title":"生食、寄生虫与免疫","subtitle":"把暴露风险、检查线索与治疗方式区分开","core":["课堂提醒：长期胃肠或免疫相关问题，不能只想到营养缺乏，也要询问生食、旅行与其他暴露。","食用生或未熟鱼类可能带来寄生虫风险；喝酒、蘸芥末不能替代有效的食品安全处理。","吃过生食不等于必然感染，预防也不等于人人定期服同一种驱虫药。"],"cards_heading":"从接触机会到实际判断","cards":[{"title":"暴露从哪里来","bullets":["<b>生食与未熟食物：<\/b>课堂主要举鱼生、生猪肉和生牛肉为例，提醒来源与加工方式的重要性。","<b>淡水与海水：<\/b>两者都不能笼统看成零风险；不同动物、地域和寄生虫需要分别了解。","<b>生活环境：<\/b>儿童接触泥土后把手放入口中、饮水与食物清洁情况，都是问诊可记录的线索。","<b>宠物相关：<\/b>关注具体传播途径；不能把“养宠物”直接等同于感染，也不能认为完全无风险。"]},{"title":"症状为什么不够","bullets":["<b>表现有差异：<\/b>不同感染可有胃肠症状、全身表现或暂时没有明显症状，不能靠感觉排除。","<b>营养与免疫：<\/b>讲师讨论了营养消耗和免疫激活两条思路，但不能解释每个人的所有症状。","<b>血常规线索：<\/b>原稿在嗜碱、嗜酸粒细胞名称上有口误；单个指标不能确诊或排除感染。","<b>检查选择：<\/b>需要把吃过什么、何时吃、到过哪里告诉医生，再决定检查与治疗方向。"]},{"title":"预防与处理","bullets":["<b>首要环节：<\/b>以安全来源、充分烹熟和规范加工降低暴露，比吃完后自行补救更可靠。","<b>冷冻有条件：<\/b>灭活效果取决于温度、时间和对象，普通短时冷冻不能直接视作可靠保证。","<b>治疗各不同：<\/b>例如异尖线虫可能需内镜处理，说明驱虫药不能对所有寄生虫一概通用。","<b>课堂经验：<\/b>讲师提到周期性驱虫，但原稿未交代适用地区、虫种和个人禁忌，不能普遍照做。"]}],"table":{"title":"常见想法与应保留的判断","headers":["想法","容易漏掉什么","更准确的理解"],"rows":[["海鱼一定没有虫","不同鱼类与虫种","来源和处理条件仍要核实"],["酒精或芥末能杀虫","处理浓度、时间及有效性","不能代替规范加热或加工"],["没有症状就没感染","部分感染可隐匿","结合暴露史和必要检查"],["一种药定期吃就够","虫种、部位和个人状态","治疗方案需针对具体问题"]]},"bottom_heading":"弓形虫的课堂补充","bottom":[{"title":"值得记住的接触环节","bullets":["课堂强调猫粪接触；处理猫砂后洗手，减少粪口传播机会。","食物与土壤也可能涉及传播，不能只盯住是否摸过猫。","孕期和免疫功能低下人群需要更谨慎地评估暴露。"]},{"title":"核查后修正的说法","bullets":["“只影响胎儿”不完整：CDC 指出弓形虫也可造成眼病及免疫低下者的严重疾病。","课堂给出的美国携带比例未附出处，本笔记不采用该数字。","发现可疑暴露后，重点是准确记录与评估，不凭恐惧反复吃药。"]}],"caution":"本页保留的是暴露识别思路；未把课堂“每年驱虫”或“吃生食就一定感染”写成通用结论。","sources":["D1-3 00:31:37—00:40:41"],"number":14,"id":"topic-14","group":1,"references":[{"id":"P2-R6","title":"CDC：About Anisakiasis","url":"https://www.cdc.gov/anisakiasis/about/","supports":"生鱼寄生虫风险、规范熟制与冷冻、异尖线虫诊疗"},{"id":"P2-R7","title":"CDC：People at Increased Risk for Toxoplasmosis","url":"https://www.cdc.gov/toxoplasmosis/risk-factors/index.html","supports":"孕期及免疫低下人群的弓形虫风险，非仅胎儿受影响"}]},{"title":"脑肠轴与迷走神经","subtitle":"观察感觉、消化与神经调节之间的联系","core":["脑与肠之间存在双向联系：内脏信息影响脑的处理，神经调节也参与消化功能。","迷走神经有感觉传入和运动传出成分；课堂强调传入信息，不能把它只理解成单向控制线。","胃肠不适和咽反射变化都不能单独证明“脑干坏了”；课堂观察需要与规范检查分开。"],"cards_heading":"从功能联系读懂课堂演示","cards":[{"title":"感觉与调节","bullets":["<b>来自内脏的信号：<\/b>食物、牵张及化学变化等信息参与饥饿、饱腹与不适的感受。","<b>神经与消化配合：<\/b>课堂把消化液、内脏运动及脑的状态联系起来，强调基础环节的相互影响。","<b>脑肠互动障碍：<\/b>部分功能性消化不良与脑肠互动有关，不代表症状是装出来或不存在。","<b>不能倒推：<\/b>腹胀、早饱、恶心或晕车可有多种原因，不能仅凭这些表现定位脑干损伤。"]},{"title":"课堂观察内容","bullets":["<b>记录症状：<\/b>餐前还是餐后、少量即饱还是缺少饱腹感，以及排便变化，都比“胃不好”具体。","<b>咽部观察：<\/b>讲师演示了发声时软腭活动和咽反射，用于说明相关脑神经的查体思路。","<b>核查补充：<\/b>健康人也可双侧咽反射缺如，尤其老年人；不能将无反应直接判为疾病。","<b>观察的边界：<\/b>反射检查需要结合声音、吞咽与其他神经体征，不鼓励自行反复刺激咽部。"]},{"title":"训练与反馈","bullets":["<b>课堂方法：<\/b>讲师用漱口、呼吸和腹部机械刺激演示调节思路，属于课程实操记录。","<b>呼吸特点：<\/b>强调呼气相对延长、避免颈肩过度用力；不把特定秒数视为每个人的统一标准。","<b>反馈指标：<\/b>课堂观察心率与血氧，但单次数字变化不能证明迷走神经修复或脑干定位。","<b>反复不适：<\/b>需要重新评估原因；不能把心慌、早搏或吞咽问题仅交给呼吸和漱口处理。"]}],"table":{"title":"消化观察如何写得更具体","headers":["观察项目","课堂关注","不能直接得出的结论"],"rows":[["进食与症状时间","餐前、餐后、饥饿时的差别","不能单靠时间确定病因"],["排便与食物关系","性状、频率、是否长期变化","漂浮大便并非必然缺胆汁"],["咽反射与软腭","神经查体中的部分信息","不能直接判断一侧大脑功能"],["问卷风险分数","帮助整理主观症状","课程阈值不等于临床诊断标准"]]},"bottom_heading":"复习与应用的分界","bottom":[{"title":"本节最重要的联系","bullets":["营养支持效果不只由吃进去的量决定，也受到消化与身体状态影响。","记录变化应兼顾原有症状、生活节律、饮食与用药。","短暂好转是观察结果；原因解释还需要更多证据。"]},{"title":"原稿未能支持的推断","bullets":["“胃肠不好等于脑干不好”是过度简化，不能当作诊断公式。","课程问卷的题目、计分方法和验证研究未完整提供，不能计算个人患病概率。","腹部按压和咽部刺激不作为本笔记的居家操作教程。"]}],"caution":"本页描述课堂演示，不提供通过咽反射自诊断脑损伤的方法；持续症状仍需要对应的医学评估。","sources":["D2-1 00:00:01—00:53:22","D2-1 00:53:22—01:09:01"],"number":15,"id":"topic-15","group":1,"references":[{"id":"P2-R8","title":"NIDDK：Symptoms & Causes of Indigestion","url":"https://www.niddk.nih.gov/health-information/digestive-diseases/indigestion-dyspepsia/symptoms-causes","supports":"功能性消化不良是脑肠互动障碍，症状不能简单定位脑干"},{"id":"P2-R9","title":"MSD Manual：How To Assess the Cranial Nerves","url":"https://www.msdmanuals.com/professional/neurologic-disorders/neurologic-examination/how-to-assess-the-cranial-nerves","supports":"健康人尤其老年人可双侧咽反射缺如，不应单独判为疾病"}]},{"title":"疼痛、平衡与营养","subtitle":"按课堂思路理解功能支持，保留诊断与证据边界","core":["疼痛是受身体、情绪与经历共同影响的体验；局部组织变化与疼痛程度并非简单一一对应。","课堂把躯干稳定、平衡、情绪与小脑联系起来，目的是解释营养支持的思路，并非提供通用定位公式。","补充某种营养素不等于证明存在缺乏，也不等于已经修复了某个脑区。"],"cards_heading":"课堂的三层解释","cards":[{"title":"从疼痛到功能","bullets":["<b>疼痛有多重因素：<\/b>外周伤害信息、中枢处理、情绪与经验会共同影响一个人的疼痛体验。","<b>稳定与代偿：<\/b>讲师用躯干不稳后肌肉持续收紧的例子，解释动作控制与不适可能有关。","<b>观察平衡：<\/b>课堂用站立表现说明稳定性；需要考虑视觉、前庭、感觉和肌力等共同作用。","<b>保留区别：<\/b>站不稳、焦虑、颈肩腰痛不能直接确认为小脑病变，也不能排除局部病因。"]},{"title":"外侧相关的课堂组合","bullets":["<b>维生素 B1：<\/b>讲师将其放在能量代谢与饮酒背景中讨论，不是把所有焦虑都归为缺 B1。","<b>镁：<\/b>用于解释多种酶反应、能量利用和神经活动需要矿物质参与，不能当作单一镇静剂。","<b>DHA：<\/b>课堂强调细胞膜材料与神经网络支持；机制上的作用不保证补充后的临床效果。","<b>整体条件：<\/b>饮酒、饮食、睡眠与实际营养状态都需考虑，不能一边持续损耗一边只加补剂。"]},{"title":"中线相关的课堂组合","bullets":["<b>辅酶 Q10：<\/b>讲师以能量代谢解释其作用，并把它纳入小脑中线相关的课堂支持方案。","<b>维生素 E：<\/b>作为抗氧化相关成分讨论；需要与其他来源合计，不能只看单瓶标示。","<b>谷胱甘肽：<\/b>属于课堂抗氧化支持思路，不能由症状直接判断体内缺多少。","<b>附加成分：<\/b>课中还提到 B12、磷脂酰丝氨酸和锌，但没有形成可普遍套用的诊断标准。"]}],"table":{"title":"课堂分组：用于复习，不用于自行选方","headers":["课堂侧重点","提到的成分","需要补充的判断"],"rows":[["躯干痛与焦虑","B1、镁、DHA","症状是否有其他病因；是否真实缺乏"],["中线稳定相关","维生素 E、Q10、谷胱甘肽","尚不能由站立表现确定脑区营养需求"],["额外支持","B12、磷脂酰丝氨酸、锌","成分叠加的必要性与相互作用"],["饮酒背景","尤其强调 B1","补剂不能抵消持续饮酒造成的风险"]]},"bottom_heading":"把机制、缺乏与效果分开","bottom":[{"title":"理解机制的价值","bullets":["记住能量、膜结构、神经传递和抗氧化几类作用，比死记一串名称更有用。","课堂组合说明讲师如何思考，不等于随机对照研究已证实该组合。","真正的结果需要看疼痛、活动能力和日常功能，而不只看补了多少。"]},{"title":"核查补充：镁的量","bullets":["NIH 给出的成人推荐总摄入量约每日 310—420 毫克，随年龄和性别而变。","成人补剂及药物来源的镁通常以每日 350 毫克为可耐受最高摄入量，不包括食物中的镁。","肾功能异常及同时用药者尤其需要评估；课堂补充量不能直接照搬。"]}],"caution":"原稿把疼痛称为“运动输出”是课堂表述；这里按疼痛体验与多因素影响整理，未将营养组合写成止痛处方。","sources":["D2-1 01:09:01—01:31:14"],"number":16,"id":"topic-16","group":1,"references":[{"id":"P2-R10","title":"NINDS：Pain","url":"https://www.ninds.nih.gov/health-information/disorders/pain","supports":"疼痛受生物、心理、社会因素共同影响，不能只以部位或组织损伤推断"},{"id":"P2-R11","title":"NIH ODS：Magnesium - Health Professional Fact Sheet","url":"https://ods.od.nih.gov/factsheets/magnesium-HealthProfessional/","supports":"成人总摄入推荐量310—420毫克；补剂来源UL350毫克；过量及相互作用"}]},{"title":"四肢关节与动作控制","subtitle":"区分疼痛、稳定性、软骨变化和代谢性问题","core":["课堂强调观察动作与受力方式，不把影像上看到的磨损直接等同于疼痛原因。","下蹲、起身、上下楼是不同任务，稳定、肌力与离心控制的需求也不同。","局部结构、炎症、神经与代谢问题可以同时存在；不能只用疼痛部位定位某个脑区。"],"cards_heading":"课堂观察的三个角度","cards":[{"title":"动作与控制","bullets":["<b>上肢任务：<\/b>讲师更关注精细动作与主动控制，提醒手、肩问题需要看完整运动链。","<b>下肢任务：<\/b>课堂突出平衡、承重与重复步行，说明单个关节可能承担其他部位的代偿。","<b>离心控制：<\/b>肌肉在受力时逐渐拉长，帮助控制下降速度；下楼与下蹲常涉及这一能力。","<b>观察方式：<\/b>比较两侧、速度和动作平顺性，但疲劳、疼痛及局部限制都可能影响表现。"]},{"title":"软骨与受力","bullets":["<b>组织特点：<\/b>课堂借关节液与负荷变化解释软骨营养，强调有规律的活动与关节环境。","<b>受力质量：<\/b>稳定的动作与异常剪切力不同，不能只说“活动过就等于营养充分”。","<b>影像与症状：<\/b>结构退变可与疼痛程度不一致，评估要结合功能、病史及其他检查。","<b>营养材料：<\/b>课中提到氨糖与胶原蛋白，但补入材料不意味着一定重建软骨。"]},{"title":"骨刺与其他病因","bullets":["<b>骨的适应：<\/b>讲师用应力与骨重塑说明骨性变化，提醒注意长期受力和活动模式。","<b>不要承诺消失：<\/b>原稿也提醒不能保证通过手法消除骨刺，不能用影像变化当唯一目标。","<b>炎症背景：<\/b>类风湿关节炎等需要独立诊治，不能只归入稳定性或营养问题。","<b>代谢背景：<\/b>痛风、糖尿病相关神经病变与一般机械性疼痛不同，处理目标也不同。"]}],"table":{"title":"四类目标不能混为一谈","headers":["关注目标","课堂举例","实际要核对"],"rows":[["动作与功能","控制、稳定、下降动作","疼痛、肌力、关节活动度及神经因素"],["炎症活动","姜黄素、维生素 D 的讨论","是否确有炎症性疾病及既定治疗"],["软骨结构","氨糖、胶原蛋白","作用证据与功能收益，不能保证再生"],["代谢问题","痛风、糖尿病相关问题","对应疾病指标、药物与生活管理"]]},"bottom_heading":"如何复习本节的观察思路","bottom":[{"title":"把动作描述清楚","bullets":["具体写下哪一个动作、哪个阶段、哪个位置出现不适。","观察相邻关节与两侧表现，避免只盯住最疼的一个点。","把功能变化与疼痛变化分别记录，二者不必同步。"]},{"title":"不把简化模型当诊断","bullets":["“上肢找大脑、下肢找小脑”是课堂口诀，不能替代神经和骨科检查。","氨糖、软骨素的临床研究结果不一致；结构修复效果仍不确定。","原稿多次指向现场课件的“一、三、四”，未完整念出成分，本笔记不补猜。"]}],"caution":"本页不提供关节挤压或手法操作教程；“下楼膝痛等于基底核异常”缺乏足够诊断依据。","sources":["D2-1 01:31:14—01:57:34"],"number":17,"id":"topic-17","group":1,"references":[{"id":"P2-R10","title":"NINDS：Pain","url":"https://www.ninds.nih.gov/health-information/disorders/pain","supports":"疼痛受生物、心理、社会因素共同影响，不能只以部位或组织损伤推断"},{"id":"P2-R12","title":"NCCIH：Glucosamine and Chondroitin for Osteoarthritis","url":"https://www.nccih.nih.gov/health/glucosamine-and-chondroitin-for-osteoarthritis-what-you-need-to-know","supports":"氨糖与软骨素对症状及结构作用的研究结果不一致"}]},{"title":"血脑屏障与脑雾","subtitle":"区分屏障功能、神经免疫与主观认知症状","core":["血脑屏障参与调节血液与脑组织间的物质交换，不是简单地让所有物质自由通过。","课堂把感染、脑外伤、炎症与脑雾联系起来；这些讨论不能据此推断个人屏障已经受损。","脑雾是一组主观认知体验，原因不止一种；吃某种补剂后有效也不能反证血脑屏障破损。"],"cards_heading":"课堂的机制主线","cards":[{"title":"屏障与物质进入","bullets":["<b>选择性：<\/b>脑内需要某种物质，不等于口服这种物质就能以有效数量到达目标位置。","<b>运输问题：<\/b>消化吸收、血液运输、屏障通过及细胞利用是连续但不同的环节。","<b>课堂关联：<\/b>讲师以脑外伤、感染和化学物质暴露说明屏障可能受影响的情境。","<b>个体判断：<\/b>真实的暴露程度、病程与其他检查缺一不可，不能只用症状完成定位。"]},{"title":"小胶质细胞","bullets":["<b>神经免疫：<\/b>课堂强调小胶质细胞参与脑内免疫活动，而不只是把神经元看作独立单位。","<b>维护工作：<\/b>讲师提到清理损伤、处理细胞碎片以及神经连接的修整等作用。","<b>双重角色：<\/b>正常应答有其用途；持续或过度激活与保护性反应不能混为一谈。","<b>系统联系：<\/b>身体炎症可能影响脑的状态，但不能写成身体与大脑必然同步发炎。"]},{"title":"课堂营养讨论","bullets":["<b>维生素 D：<\/b>被放在免疫调节的位置；课堂经验中的高剂量不能当成脑雾标准治疗。","<b>抗氧化成分：<\/b>提到姜黄素、白藜芦醇和褪黑素，作用机制不等于组合疗效已确认。","<b>草本部分：<\/b>课中强调西洋参并讨论黄芪；不同植物不能仅因名称相近就互相替代。","<b>来源限制：<\/b>“画红线的三种”依赖现场课件，文字稿无法完整还原，不能自行补齐。"]}],"table":{"title":"几个容易混淆的推断","headers":["课堂话题","可保留的理解","不能直接推出"],"rows":[["感染后脑雾","记录时间、认知与日常功能变化","每个人都存在同一种屏障损伤"],["GABA 补剂有效","主观变化需要进一步解释","一定通过屏障且证明屏障漏了"],["免疫调节","生理机制与营养状态有关","大剂量维生素能普遍修复屏障"],["抗氧化与草本","是课堂提出的支持方向","多种一起用必然更有效或安全"]]},"bottom_heading":"复习时保留两条主线","bottom":[{"title":"认识症状","bullets":["把脑雾写具体：注意力、记忆、反应速度或完成日常任务的变化。","同时记录感染、睡眠、用药和受伤史，避免只追求一种解释。","持续或加重的认知变化需要评估，不以补剂反应代替诊断。"]},{"title":"看懂方案边界","bullets":["维生素 D 的日常摄入、安全上限和医学治疗剂量是三个不同概念。","姜黄素制剂的实际含量与利用度差异大，也存在不良反应。","原稿的儿童同配方、按胶囊数加量与草本“一把”用量均未转写成操作建议。"]}],"caution":"“吃 GABA 有效就说明血脑屏障漏了”不能成立为诊断；本页保留机制讨论，不承诺补剂修复屏障。","sources":["D2-1 01:57:34—02:12:21"],"number":18,"id":"topic-18","group":1,"references":[{"title":"NIH ODS｜维生素D专业资料","url":"https://ods.od.nih.gov/factsheets/VitaminD-HealthProfessional/","supports":"维生素D过量可中毒；成人常规UL为每日4000 IU，儿童随年龄不同，UL不是补充建议。"},{"id":"P2-R4","title":"NCCIH：Turmeric: Usefulness and Safety","url":"https://www.nccih.nih.gov/health/turmeric","supports":"姜黄素制剂差异、疗效证据局限及高利用度产品的肝损伤风险"}]},{"title":"DHA、EPA 与脂肪来源","subtitle":"看清成分、饮食背景，以及补剂和药物各自的用途","core":["DHA 与 EPA 都属于长链 Omega-3 脂肪酸，不能把鱼油总量等同于其中任一种的含量。","课堂用 DHA 解释脑与视网膜的膜结构，用 EPA 讨论外周炎症；这种分工不应被绝对化。","营养补充不能替代已经开具的降脂治疗；“他汀必然加速脑退化”与现有主要证据不符。"],"cards_heading":"先看结构，再看来源和利用","cards":[{"title":"两种脂肪酸","bullets":["<b>DHA：<\/b>是脑内细胞膜磷脂的重要成分；课堂强调其与神经、视网膜及细胞材料的关系。","<b>EPA：<\/b>同样属于 Omega-3，参与多种生理过程，不能理解为只作用在身体而与脑完全无关。","<b>膜的材料：<\/b>有必要的营养原料才能维持功能，但补充之后的效果仍取决于基础状态。","<b>证据层级：<\/b>观察到饮食关联，和证明补剂能预防或治疗认知衰退，是不同问题。"]},{"title":"来源与消化","bullets":["<b>课堂来源：<\/b>鱼类、鱼油和海藻油都被提到，产品中 DHA、EPA 比例可能相差很大。","<b>每份含量：<\/b>看每份需要几粒，再分别核对 DHA 和 EPA；瓶身标称重量不能直接代入。","<b>利用条件：<\/b>脂肪消化吸收出现问题时，单纯增加口服量可能无法解决根本原因。","<b>饮食整体：<\/b>课堂强调脂肪结构与烹饪习惯，但不能只用 Omega-6 与 Omega-3 的比值评判全部饮食。"]},{"title":"用药与代谢","bullets":["<b>课堂担忧：<\/b>讲师讨论了他汀、辅酶 Q10、胆固醇与脑功能，这些需要分别核查。","<b>已核查：<\/b>AHA 科学声明指出，多数观察研究与随机试验不支持他汀导致认知损害或痴呆的结论。","<b>不能替代：<\/b>控糖、B 族维生素、鱼油或 Q10 不能自行组合成已证实的他汀替代方案。","<b>生活与治疗：<\/b>饮食、活动和处方药可有不同作用，是否调整药物应依据具体风险评估。"]}],"table":{"title":"读标签时要分开的信息","headers":["标签内容","含义","常见误读"],"rows":[["鱼油总重量","整份油脂的质量","把它直接当成 DHA 含量"],["EPA 与 DHA","分别标示的有效成分量","只看总 Omega-3，不看组成"],["每份粒数","计算一份所需的数量","把每份含量误当成每粒含量"],["产品与用药","不同的用途和证据要求","把营养补充当作药物替代"]]},"bottom_heading":"课堂观点中需要修正的部分","bottom":[{"title":"关于油脂的说法","bullets":["原稿没有可靠资料支持“猪油一定最耐高温、比例最好”，本笔记不采用该排序。","Omega-6 也是必需脂肪酸，不能把含有它的食物一概标成促炎食物。","烹饪加热后的氧化变化与工业氢化不是同一个过程。"]},{"title":"关于脑健康的说法","bullets":["“EPA 完全不能通过血脑屏障”过于绝对，本页不据此作硬性分工。","脑白质影像异常有多种原因，不能直接读成缺 DHA 或必须补 Q10。","药物获益、个人不良反应与营养需求应分别记录，再与医生讨论。"]}],"caution":"已核查的关键修正：不要依据本课程停止或用补剂替代他汀；课堂所述必然导致脑退化不受主要研究支持。","sources":["D2-1 02:12:21—02:28:30"],"number":19,"id":"topic-19","group":1,"references":[{"id":"P2-R13","title":"NIH ODS：Omega-3 Fatty Acids - Health Professional Fact Sheet","url":"https://ods.od.nih.gov/factsheets/Omega3FattyAcids-HealthProfessional/","supports":"DHA在脑膜磷脂中的作用，饮食与补剂的认知获益证据需区分"},{"id":"P2-R14","title":"AHA：Aggressive LDL-C Lowering and the Brain","url":"https://professional.heart.org/en/science-news/aggressive-ldl-c-lowering-and-the-brain-impact-on-risk-for-dementia-and-hemorrhagic-stroke","supports":"多数观察研究与随机试验不支持他汀或降LDL导致认知损害、痴呆"}]},{"title":"铁、贫血与供氧","subtitle":"把摄入、吸收、持续丢失和检查结果连起来","core":["铁参与血红蛋白等结构与功能；缺铁性贫血会影响氧运输，但缺铁、贫血与缺氧并非完全同义。","补充效果不好时，需要同时看摄入与吸收、持续失血、炎症及原先诊断，而不是只增加剂量。","铁蛋白会受炎症影响；应结合血常规、铁状态与临床情况判断，不能用单一数字决定补铁。"],"cards_heading":"沿着铁的去向复习","cards":[{"title":"摄入与吸收","bullets":["<b>食物来源：<\/b>课堂列举红肉、动物肝脏和血制品；植物性食物也含铁，但吸收条件有所不同。","<b>摄入不等于利用：<\/b>吃了铁剂不保证吸收充分，消化道疾病、药物和服用方式均需核对。","<b>维生素 C：<\/b>有助于非血红素铁吸收，但不能据此保证所有补铁失败都能解决。","<b>原稿技巧：<\/b>课中提出漱口后补铁；这没有被本次核查确认为通用治疗步骤。"]},{"title":"需要与丢失","bullets":["<b>生长需要：<\/b>儿童发育阶段的铁状态值得关注，但不能把发育迟缓直接等同于贫血。","<b>月经与失血：<\/b>持续或大量失血可能造成缺铁，需要明确来源，不能仅靠不断补充抵消。","<b>消化道来源：<\/b>课堂特别提醒长期便血及补上后又下降的情况，提示查找持续丢失。","<b>饮食限制：<\/b>素食者需重视铁来源和整体搭配，但并非所有素食者都必然贫血或需要铁剂。"]},{"title":"检查与表现","bullets":["<b>储备先变化：<\/b>缺铁可先表现为储备减少，尚未出现明显血红蛋白下降，不能只看是否贫血。","<b>铁蛋白：<\/b>反映储存铁的信息，但感染和炎症可使其升高，需要结合其他指标解释。","<b>血常规：<\/b>血红蛋白、红细胞相关指标提供不同信息；小细胞表现也有其他可能病因。","<b>临床线索：<\/b>疲劳、面色改变、运动耐力下降或脱发都非特异，不能单凭外观诊断缺铁。"]}],"table":{"title":"常见结果应该怎样理解","headers":["线索","可能提供的信息","还要核对什么"],"rows":[["铁蛋白偏低","储备铁不足的线索","年龄、疾病背景与化验参考范围"],["铁蛋白偏高","炎症、储备或其他因素","血常规、炎症及完整铁状态"],["血红蛋白偏低","存在贫血的线索","缺铁、B12/叶酸及其他病因"],["补充后反复下降","可能持续失血或吸收问题","失血来源、依从性及诊断是否准确"]]},"bottom_heading":"把补充过程变成可回查的记录","bottom":[{"title":"记录四类信息","bullets":["保留检查日期与报告，比较同类指标随时间如何变化。","记录饮食、铁剂名称、实际服用情况及胃肠耐受。","同时记录月经、便血、慢性病与正在使用的药物。"]},{"title":"避免三个误区","bullets":["“铁蛋白高而红细胞小就一定补铁”过于简单，需要鉴别其他原因。","皮肤白、头发少和疲劳不能单独确认缺铁，也不能据此判断儿童脑供氧。","铁过量也有风险；确认需要后再决定补充、复查和疗程。"]}],"caution":"本页未把课堂“漱口加维 C 就能避免补铁失败”作为结论；补充无效应重新核对病因与治疗方案。","sources":["D2-1 02:28:30—02:40:44"],"number":20,"id":"topic-20","group":1,"references":[{"id":"P2-R15","title":"NIH ODS：Iron - Health Professional Fact Sheet","url":"https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/","supports":"缺铁阶段、铁蛋白受炎症影响、缺铁性贫血及其他贫血病因"},{"id":"P2-R16","title":"NIDDK：Anemia of Inflammation or Chronic Disease","url":"https://www.niddk.nih.gov/health-information/blood-diseases/anemia-inflammation-chronic-disease","supports":"慢性炎症性贫血可有低血铁而组织储存铁正常，需要综合判断"}]},{"title":"B12、叶酸与贫血","subtitle":"把造血原料、吸收障碍和检验线索放在一起理解","core":["铁、维生素B12与叶酸参与造血的环节不同；贫血需要先区分原因。","B12还与神经功能有关，叶酸参与一碳代谢、DNA合成与甲基化。","课堂用红细胞大小串联缺乏类型，但单个指标或外观不能独立确诊。"],"cards_heading":"三个相互关联的学习点","cards":[{"title":"B12：造血与神经","bullets":["<b>双重角色<\/b>：课堂强调B12既支持红细胞生成，也参与神经髓鞘相关功能。","<b>摄入线索<\/b>：长期严格素食者，要留意可靠的B12食物来源或强化食品。","<b>吸收线索<\/b>：胃肠疾病、吸收障碍以及某些长期用药，可能增加缺乏风险。","<b>不要只看贫血<\/b>：出现麻木、步态或认知变化时，还需考虑神经系统评估。"]},{"title":"叶酸：细胞更新","bullets":["<b>生长与成熟<\/b>：叶酸支持细胞分裂和核酸合成，因此造血和胎儿发育都需要。","<b>同型半胱氨酸<\/b>：课堂将它与叶酸、B12的代谢联系起来，适合作为联动知识点。","<b>基因因素<\/b>：MTHFR变异可能影响叶酸代谢效率，但不等于完全不能利用普通叶酸。","<b>术语订正<\/b>：MTHFR指亚甲基四氢叶酸还原酶；原稿的酶名及活性形式表述有混淆。"]},{"title":"贫血：先找原因","bullets":["<b>体积分类<\/b>：课程按小细胞、正细胞和大细胞三类，帮助建立初步鉴别思路。","<b>不只缺营养<\/b>：持续失血、慢性疾病及其他造血问题，也可能造成贫血。","<b>身体观察<\/b>：苍白、疲劳、指甲或毛发改变只是线索，需要结合血液检查。","<b>复查逻辑<\/b>：补充后仍不改善，应重看诊断、持续失血、吸收与实际依从性。"]}],"table":{"title":"课堂分类与核查后的使用边界","headers":["观察项目","课堂关联","理解时补上一层"],"rows":[["红细胞偏小","优先想到铁不足","也有地中海贫血等原因，不能直接补铁"],["红细胞偏大","想到B12或叶酸不足","还需排查其他原因，正常体积也不能完全排除缺乏"],["红细胞体积正常","关注失血","正细胞贫血不只由出血引起"],["同型半胱氨酸升高","回看叶酸与B12","结合整体情况解读，不套用课堂单一目标值"]]},"bottom_heading":"整理与核查补充","bottom":[{"title":"复习时连成一条线","bullets":["把摄入不足、吸收不良、需求增加和持续流失分开，避免只想到加补剂。","记住血红蛋白、红细胞体积和相关营养检查各回答不同问题。","记录既往胃肠疾病和用药史，尤其是长期二甲双胍或抑酸药使用。"]},{"title":"核查补充","bullets":["NHLBI强调通过病史、血常规及进一步检查寻找贫血原因，外观观察不够。","CDC指出常见MTHFR变异者仍能利用叶酸，不需据此自行成倍加量。","大剂量叶酸可能掩盖B12缺乏的血液表现，补充前须考虑B12状态。"]}],"caution":"课堂关于MCV的个人阈值、叶酸与B12必然互相耗竭及基因变异加倍补充，不能当成统一诊疗标准。","sources":["D2-2 00:00:01.730—00:38:38.970"],"number":21,"id":"topic-21","group":2,"references":[{"title":"NHLBI：贫血诊断","url":"https://www.nhlbi.nih.gov/health/anemia/diagnosis","supports":"贫血需病史、血常规与必要的进一步检查，外观及单一体积不能确诊。"},{"title":"NIH ODS：叶酸专业资料","url":"https://ods.od.nih.gov/factsheets/Folate-HealthProfessional/","supports":"MTHFR及叶酸代谢背景；大剂量叶酸掩盖B12缺乏风险。"},{"title":"CDC：MTHFR变异与叶酸","url":"https://www.cdc.gov/folic-acid/data-research/mthfr/index.html","supports":"常见MTHFR变异者仍可代谢普通叶酸，不能直接推导成倍加量。"}]},{"title":"脱发的分类思路","subtitle":"先区分分布、脱落与断裂，再讨论可能的全身因素","core":["脱发是表现，缺乏、压力、甲状腺和不同皮肤疾病需要分别考虑。","均匀变稀、发际线变化、片状脱落与发干断裂，提供不同观察线索。","课堂列出的营养组合属于经验方案；没有确认缺乏时，不宜堆叠补剂。"],"cards_heading":"先把观察说清楚","cards":[{"title":"看分布与时间","bullets":["<b>弥漫性变化<\/b>：记录是否全头均匀减少，以及近期疾病、压力或饮食变化。","<b>局部与模式<\/b>：发际线后退、头顶变稀、片状脱落的模式不能混为一类。","<b>全身体毛<\/b>：眉毛和体毛同时减少时，课堂提示关注甲状腺等全身因素。","<b>看趋势<\/b>：比某一天掉了多少根更有用的是持续时间、密度及新发生长情况。"]},{"title":"看头皮与发干","bullets":["<b>头皮状态<\/b>：油脂、红斑、瘙痒和脓疱需要单独记录，不能只归因于营养。","<b>脱落或断裂<\/b>：头发从根部脱落与中途折断不同，后者还涉及护理和发干损伤。","<b>课堂拉发演示<\/b>：用于说明观察思路，施力和取样不规范会影响结果。","<b>术语订正<\/b>：脱落头发根部的白色末端不代表整个毛囊被拔出。"]},{"title":"课堂营养关联","bullets":["<b>压力相关<\/b>：讲师讨论茶氨酸与南非醉茄，目标是压力体验，不是直接长发。","<b>缺乏相关<\/b>：课程把铁、锌、B族和蛋白质摄入联系到头发生长材料。","<b>甲状腺相关<\/b>：讲师提到硒，但缺硒与补硒过量都不能靠脱发自行判断。","<b>配方缺页<\/b>：多处只说PPT的“第几行”，文字稿不足以还原完整成分。"]}],"table":{"title":"把问题分开，才便于继续查找","headers":["观察到的变化","课堂的关注方向","整理后的边界"],"rows":[["全头逐渐变稀","压力、贫血、甲状腺","只是鉴别线索，需要结合病程"],["发际线或头顶变化","雄激素相关脱发","由皮肤科确认具体类型"],["一片片脱落","斑秃与免疫因素","不凭外观推断特定食物过敏"],["发干易断、指甲脆","营养材料与护理","未确认缺乏不套用高剂量生物素"]]},"bottom_heading":"值得保留的记录方法","bottom":[{"title":"形成可对比记录","bullets":["在相近光线、角度下拍摄发际线和分缝，比反复拉扯头发更容易追踪。","把脱发开始时间与发热、体重变化、压力、药物及护理改变放在同一时间线。","补充剂的名称和剂量也列入记录，检查前主动告知正在使用的产品。"]},{"title":"核查补充","bullets":["NIH认为生物素改善一般人毛发的证据有限，高剂量还可能干扰甲状腺等化验。","NIH指出硒过量可导致脱发与指甲损伤；原稿硒单位存在严重疑点。","NCCIH提示南非醉茄有肝损伤报告，孕期及甲状腺疾病人群尤其需谨慎评估。"]}],"caution":"原稿的头皮针刺、注射和制造淤血属于侵入性操作，不转写为家庭生发教程。","sources":["D2-2 00:38:38.970—01:04:32.530"],"number":22,"id":"topic-22","group":2,"references":[{"title":"NIH ODS：生物素","url":"https://ods.od.nih.gov/factsheets/biotin-consumer/","supports":"一般毛发获益证据有限，高量生物素可能干扰化验。"},{"title":"NIH ODS：硒专业资料","url":"https://ods.od.nih.gov/factsheets/Selenium-HealthProfessional/","supports":"硒为微克级营养素，过量可损害毛发指甲，课堂毫克单位须核对。"},{"title":"NCCIH：南非醉茄","url":"https://www.nccih.nih.gov/health/ashwagandha","supports":"长期安全性不确定、肝损伤报告及孕期和甲状腺疾病相关注意。"}]},{"title":"免疫、炎症与食物反应","subtitle":"区分防御、过度反应和自身免疫，避免把所有不适归到同一个原因","core":["免疫系统需要识别和调节；反应不足、过强与错误攻击是不同问题。","炎症参与防御与修复，关键在于发生的原因、强度和持续时间。","食物过敏、乳糖不耐受、乳糜泻和非乳糜泻性麸质敏感不能互换名称。"],"cards_heading":"课堂主线：识别、反应、调节","cards":[{"title":"炎症如何理解","bullets":["<b>防御与修复<\/b>：课堂用清除受损组织的比喻，说明炎症并非一概有害。","<b>时间与程度<\/b>：反应持续过久或位置、对象不合适，可能伤害正常组织。","<b>常见表现<\/b>：红、肿、热、痛及功能受限有助描述，但没有这些也不能排除疾病。","<b>目标不是归零<\/b>：整理时保留调节的概念，不把抗炎理解为越强越好。"]},{"title":"自身免疫的线索","bullets":["<b>识别错误<\/b>：课堂以“认错自己”解释自身免疫，是帮助理解的简化比喻。","<b>疾病例子<\/b>：提到桥本甲状腺炎、类风湿关节炎及系统性红斑狼疮等。","<b>多因素参与<\/b>：遗传背景、免疫调节和环境因素共同作用，不能归结为一种食物。","<b>神经免疫联系<\/b>：课程讨论左右脑、小脑和免疫的关联，具体疗效仍属课堂假说。"]},{"title":"食物与肠道屏障","bullets":["<b>课堂关注<\/b>：讲师把消化、肠道通透性和食物抗原联系起来讨论。","<b>个体差异<\/b>：同一种食物引发的反应不同，需要准确的病史与针对性评估。","<b>观察有条件<\/b>：饮食调整前后变化可供记录，但不能仅凭一次好转确定病因。","<b>避免扩大禁食<\/b>：长期排除多种食物时，还要考虑蛋白质、能量和微量营养素。"]}],"table":{"title":"几种容易混淆的情况","headers":["概念","重点区别","不能直接推出"],"rows":[["食物过敏","针对食物的免疫反应","吃后不舒服都属于过敏"],["乳糖不耐受","乳糖消化吸收问题","等同于牛奶蛋白过敏"],["乳糜泻","需要规范评估的免疫疾病","仅靠戒麸质后舒服就确诊"],["非乳糜泻性麸质敏感","需与其他病因区分","所有人都应该长期无麸质"]]},"bottom_heading":"食物观察与核查补充","bottom":[{"title":"让记录更有解释力","bullets":["记录具体食物、摄入时间、症状出现时间和是否重复出现，而非只记“发炎”。","同时记下用药、睡眠和其他饮食改变，减少把多种变化误算成某一食物效果。","课堂中的单个湿疹改善案例不能证明同样的神经刺激适用于所有自身免疫病。"]},{"title":"核查补充","bullets":["NIDDK建议在乳糜泻诊断检查前不要自行开始无麸质饮食，以免影响结果。","牛奶蛋白过敏者仍可能对煮沸牛奶或酸奶反应，不能按课堂表述自行试吃。","原稿将鸡蛋蛋白与毛囊攻击直接相连，缺少足够材料支持，保留为待核说法。"]}],"caution":"有严重过敏史者不自行进行食物激发试验；“煮沸或发酵后必然不过敏”不能成立。","sources":["D2-2 01:04:32.530—01:23:54.820","D2-2 01:27:53.170—01:36:26.140"],"number":23,"id":"topic-23","group":2,"references":[{"id":"P2-R5","title":"NIDDK：Diagnosis of Celiac Disease","url":"https://www.niddk.nih.gov/health-information/digestive-diseases/celiac-disease/diagnosis","supports":"怀疑乳糜泻不宜在检查前自行无麸质饮食"},{"title":"剑桥大学医院：牛奶过敏","url":"https://www.cuh.nhs.uk/patient-information/milk-allergy/","supports":"煮沸牛奶和酸奶仍可能引起乳蛋白过敏，不能自行视为安全。"}]},{"title":"甲状腺与全身症状","subtitle":"从症状、功能、抗体和结构四个角度整理课堂内容","core":["甲状腺激素影响能量利用，因此症状可能涉及体力、体温、毛发和月经。","甲状腺功能、抗体和结节分别回答不同问题，不能只盯一项数字。","课程的营养与神经训练方案是辅助讨论，不能替代甲状腺疾病的规范治疗。"],"cards_heading":"先区分三个层次","cards":[{"title":"症状：全身表现","bullets":["<b>课堂提示<\/b>：怕冷、乏力、脱发、情绪和月经改变，被作为甲减相关线索。","<b>并不特异<\/b>：这些表现也可能来自睡眠、贫血、其他疾病或用药。","<b>甲亢方向<\/b>：课程同时提及心身兴奋与疲劳，提醒疲劳不只对应甲减。","<b>时间线<\/b>：记录症状何时出现、持续多久、与用药或生活变化有何关系。"]},{"title":"检查：各看什么","bullets":["<b>功能检查<\/b>：TSH及甲状腺激素帮助判断激素供应状态，不能被抗体替代。","<b>抗体检查<\/b>：帮助评估自身免疫背景，抗体高低并不直接等同症状严重程度。","<b>结构检查<\/b>：结节和大小属于结构层面，需要相应的影像与临床判断。","<b>触诊演示<\/b>：原课演示左右比较；摸到不对称不等于已经确定炎症。"]},{"title":"课堂辅助思路","bullets":["<b>消化与饮食<\/b>：讲师重视肠道问题和可能的食物反应，作为整体状况的一部分。","<b>营养支持<\/b>：提及维D、谷胱甘肽、辅酶Q10、镁和硒等不同作用目标。","<b>情绪与睡眠<\/b>：课中还讨论色氨酸与节律，但不能据此确定具体适应证。","<b>神经训练<\/b>：左右脑、小脑和惊吓反射的解释归入课堂经验，不当作确证病因。"]}],"table":{"title":"复习时不要混用这些判断","headers":["层面","能够帮助回答","不能替代"],"rows":[["怕冷、疲劳等症状","是否需要继续评估","病因诊断与实验室检查"],["TSH与甲状腺激素","功能是否异常","结节性质评估"],["甲状腺相关抗体","是否支持自身免疫背景","全部用药决策"],["超声和必要的进一步检查","结构、结节及风险特征","单靠触诊下结论"]]},"bottom_heading":"将课堂思路放回完整评估","bottom":[{"title":"适合记住的联系","bullets":["毛发、月经和情绪的变化可能与同一个全身问题有关，整理病史时可以一起问。","不因某种补剂后主观好转，就推断甲状腺功能已恢复或可以停药。","记录全部补充剂，尤其是含碘、硒和生物素产品，便于检查和用药评估。"]},{"title":"核查补充","bullets":["NIDDK介绍桥本病时强调病史、激素及抗体检查，必要时使用超声。","发生甲减时，医生通常以甲状腺激素替代治疗；营养补充不等于替代治疗。","是否需要补硒不能由抗体下降案例决定，摄入过多会造成脱发等不良反应。"]}],"caution":"“所有甲状腺问题都由肠道或小脑引起”“无症状结节不用管”均不能从这份课堂记录直接推出。","sources":["D2-2 01:16:04.530—01:27:48.810","D2-2 01:48:58.850—01:59:46.550"],"number":24,"id":"topic-24","group":2,"references":[{"title":"NIDDK：桥本病","url":"https://www.niddk.nih.gov/health-information/endocrine-diseases/hashimotos-disease","supports":"桥本病症状、激素和抗体评估及甲减治疗。"},{"title":"NIH ODS：硒专业资料","url":"https://ods.od.nih.gov/factsheets/Selenium-HealthProfessional/","supports":"硒为微克级营养素，过量可损害毛发指甲，课堂毫克单位须核对。"},{"title":"NIH ODS：生物素","url":"https://ods.od.nih.gov/factsheets/biotin-consumer/","supports":"一般毛发获益证据有限，高量生物素可能干扰化验。"}]},{"title":"维生素D、K2与镁","subtitle":"理解相关作用，也分清推荐摄入量、补充量和医疗剂量","core":["维生素D涉及钙代谢和免疫功能，但不意味着高剂量适合所有人。","维生素K参与凝血及相关蛋白功能；K2不能保证消除高剂量维D风险。","镁参与多种酶反应与神经肌肉功能，选择补剂要看元素镁含量及耐受。"],"cards_heading":"三种营养素的课堂定位","cards":[{"title":"维生素D","bullets":["<b>课程重点<\/b>：讲师反复把维D放在免疫调节和整体营养支持的重要位置。","<b>作用不只骨骼<\/b>：除钙吸收外，也参与多种细胞过程，但作用机制不等于治疗证据。","<b>目标要明确<\/b>：纠正缺乏与治疗某种疾病是不同问题，不能共享同一套剂量。","<b>评估条件<\/b>：是否补充、补多少和何时复查，应结合具体健康状况与用药。"]},{"title":"维生素K2","bullets":["<b>课堂比喻<\/b>：讲师用“让钙去该去的地方”描述K2的作用，便于记忆但不够完整。","<b>认识形式<\/b>：K2是一组甲萘醌，不能因为有不同结构就否认其维生素身份。","<b>证据边界<\/b>：原稿把它用于逆转血管钙化，不能直接当成已证实的普遍疗效。","<b>用药相关<\/b>：使用华法林等药物者需要维持维K摄入稳定，不能随意增减。"]},{"title":"镁","bullets":["<b>广泛参与<\/b>：能量代谢、神经传导、肌肉活动等都需要镁参与。","<b>读标签<\/b>：关注每份含多少元素镁，不能把某种镁盐总重量当成镁含量。","<b>形式与耐受<\/b>：甘氨酸镁、柠檬酸镁等产品在剂型与耐受上存在差别。","<b>课堂选择<\/b>：讲师偏好苏糖酸镁用于脑功能；“唯一能进入大脑”仍需证据限定。"]}],"table":{"title":"核查补充：几个数字与概念要分清","headers":["项目","权威资料中的参考","不能误读为"],"rows":[["成人维D摄入上限","NIH列一般成人为4000 IU/日","人人都应补到上限，或医疗剂量可自行使用"],["成人镁推荐摄入","NIH列一般成人约310—420 mg/日","全部都从补剂摄入"],["补剂和药物中的镁上限","一般成人350 mg/日，不含天然食物镁","肾病患者也可按此自行补充"],["维K与华法林","摄入变化可能影响抗凝效果","K2的凝血影响可以忽略"]]},"bottom_heading":"把补充方案看完整","bottom":[{"title":"购买前先核对","bullets":["把复合维生素、单方产品和其他含同成分产品合并计算，避免重复。","区分IU、毫克和微克；剂量单位错一档可能造成很大的实际差异。","出现腹泻、恶心或其他异常，不应只解释为身体正在调整。"]},{"title":"课堂与核查的差别","bullets":["课堂高剂量维D方案不收入可执行卡片；过量可能造成高钙血症和肾损害。","K2不能被当作超量维D的保险，也不能替代血管疾病的评估与治疗。","镁不是所有抽筋或失眠的统一答案，肾功能受损者尤其需要专业评估。"]}],"caution":"本页数字为核查资料中的参考范围，并非个人补充处方；课堂大剂量原话已放入疑点记录。","sources":["D2-2 01:36:26.140—01:42:38.850","D2-2 01:56:45.250—01:59:02.330","D2-3 00:00:29.100—00:04:12.240"],"number":25,"id":"topic-25","group":2,"references":[{"title":"NIH ODS｜维生素D专业资料","url":"https://ods.od.nih.gov/factsheets/VitaminD-HealthProfessional/","supports":"维生素D过量可中毒；成人常规UL为每日4000 IU，儿童随年龄不同，UL不是补充建议。"},{"title":"NIH ODS：维生素K","url":"https://ods.od.nih.gov/factsheets/vitaminK-HealthProfessional/","supports":"华法林等抗凝药与维K的相互作用。"},{"id":"P2-R11","title":"NIH ODS：Magnesium - Health Professional Fact Sheet","url":"https://ods.od.nih.gov/factsheets/magnesium-HealthProfessional/","supports":"成人总摄入推荐量310—420毫克；补剂来源UL350毫克；过量及相互作用"}]},{"title":"断食、生酮与自噬","subtitle":"把饮食安排、供能状态和细胞过程分开理解","core":["断食是一种进食安排，生酮是一种代谢状态，自噬是细胞内过程。","课中用“系统重启”解释潜在变化，是比喻，不能直接等同临床疗效。","时间受限进食的研究结果不能直接推广为自行长期断食治疗免疫或神经疾病。"],"cards_heading":"三个名词，三个层面","cards":[{"title":"断食：改变进食窗口","bullets":["<b>课堂出发点<\/b>：讲师希望通过进食时间与能量摄入改变，讨论代谢的可塑性。","<b>不是只看时长<\/b>：总能量、营养是否足够、作息和依从性，都影响结果。","<b>研究条件<\/b>：研究中的筛选、教育、监测和药物调整，是方案的一部分。","<b>个体差异<\/b>：同一进食窗口，对不同疾病、用药和营养状态的人风险不同。"]},{"title":"生酮：供能方式变化","bullets":["<b>代谢理解<\/b>：碳水可用性减少等条件下，肝脏可增加酮体生成，为组织提供能量。","<b>测量范围<\/b>：血酮或尿酮能反映酮体相关状态，不能直接测出人体自噬程度。","<b>中链脂肪<\/b>：课堂以椰子油举例，但椰子油与纯MCT产品组成不同。","<b>术语订正<\/b>：原稿先说不经肝脏，后又说肝内转酮；整理采用肝脏参与酮体生成。"]},{"title":"自噬：细胞内更新","bullets":["<b>基本概念<\/b>：细胞通过相关过程处理部分受损组分并回收材料，不是只在饥饿时存在。","<b>课堂比喻<\/b>：讲师用“清理垃圾”帮助理解，但人体内的调控复杂得多。","<b>不能用外观证实<\/b>：皮肤变滑、精神清醒或不饿，都不能确定自噬是否达到某个程度。","<b>疗效边界<\/b>：原课把特定小时数对应代谢、免疫和神经改善，不能当作通用阈值。"]}],"table":{"title":"同一个现象不等于同一个结论","headers":["观察或做法","可以说明什么","不能证明什么"],"rows":[["缩短每日进食窗口","改变了进食时间安排","已经治疗某一种慢性病"],["测到酮体","发生了相应的代谢变化","自噬增强或疾病正在好转"],["短期体重下降","体重发生变化","减少的全部是脂肪"],["精神或皮肤主观改善","体验发生变化","神经退化或自身免疫问题已逆转"]]},"bottom_heading":"核查补充与复习重点","bottom":[{"title":"核查补充","bullets":["NIH报道部分2型糖尿病人群的限时进食研究有体重和血糖获益，参与者接受监测。","IDF提示糖尿病人断食可能出现低血糖、高血糖、脱水或酮症酸中毒。","使用胰岛素等降糖药者，不能在不调整方案和不监测的情况下照搬断食。"]},{"title":"这页真正要记住","bullets":["先讲清目标，再看适合谁、证据如何、需要什么监测，不能只背小时数。","营养不足、妊娠、未成年人和有进食障碍风险者，不把课堂断食当作自助任务。","出现疑似低血糖时先中止断食并处理低血糖，不为维持所谓自噬而硬撑。"]}],"caution":"原稿的长时断食安排、低血糖不吃糖及自行恢复饮食说法不作为操作指引；具体疑点另存。","sources":["D2-2 01:59:46.550—02:15:44.150","D2-2 02:39:03.210—02:43:28.620","D2-3 00:20:33.210—00:21:28.530"],"number":26,"id":"topic-26","group":2,"references":[{"title":"NIH：2型糖尿病人群限时进食研究","url":"https://www.nih.gov/news-events/nih-research-matters/intermittent-fasting-weight-loss-people-type-2-diabetes","supports":"特定研究中的限时进食获益及教育监测条件，不能等同长时断食治病。"},{"title":"IDF：糖尿病与断食","url":"https://idf.org/managing-diabetes/fasting/","supports":"断食的个体风险、用药调整和监测要求。"},{"title":"NIDDK：低血糖","url":"https://www.niddk.nih.gov/health-information/diabetes/overview/preventing-problems/low-blood-glucose-hypoglycemia","supports":"成人低血糖快速糖类处理及复测原则。"}]},{"title":"血糖、肥胖与尿酸","subtitle":"把代谢风险、实际检测和症状变化放在同一张笔记里","core":["课中强调先调整饮食与生活方式，不靠补剂抵消长期不合适的摄入。","饭后困、饥饿时心情变化只是观察线索，不能直接诊断胰岛素抵抗。","高尿酸与痛风疼痛有关但不相同，疼痛消失不代表尿酸已经达标。"],"cards_heading":"从课堂案例提取判断顺序","cards":[{"title":"血糖：区分概念","bullets":["<b>胰岛素抵抗<\/b>：指组织对胰岛素反应降低，与血糖高低不是同一个概念。","<b>课堂观察<\/b>：餐后困倦、空腹不适和皮肤褶皱变深，被用作提示进一步观察。","<b>不能单凭体感<\/b>：这些表现还有其他原因，需要结合检测和病史。","<b>高低都要记录<\/b>：尤其使用降糖药者，应记录低血糖的时间、饮食和药物背景。"]},{"title":"体重：先看基础","bullets":["<b>课程主张<\/b>：先改变不合适的饮食结构，再考虑辅助措施，不能用补剂代偿。","<b>看长期模式<\/b>：总能量、食物质量、体力活动与睡眠共同影响体重管理。","<b>避免单一归因<\/b>：不能把所有肥胖或疲劳都解释为碳水过多或胰岛素抵抗。","<b>辅助品的边界<\/b>：课中提到苹果醋和小檗碱，但它们不能替代糖尿病的管理方案。"]},{"title":"尿酸：分清两个目标","bullets":["<b>症状控制<\/b>：关节红肿痛是否缓解，是观察痛风急性发作的重要层面。","<b>长期管理<\/b>：尿酸水平和结晶负担需要独立评估，不能仅凭不痛判断。","<b>饮食关注<\/b>：课堂特别强调果糖；整理时重点记录含糖饮料、酒精及整体饮食。","<b>经验食物<\/b>：油柑、芹菜叶及多种补剂属于课堂经验，不列为已证实降尿酸处方。"]}],"table":{"title":"观察线索与下一步问题","headers":["现象","先补充什么信息","不要直接下的结论"],"rows":[["饭后困、饿了难受","餐量、睡眠、血糖、用药","一定存在胰岛素抵抗"],["出汗、手抖、心慌","及时测血糖并评估症状","只是缺乏酮体适应"],["关节突然红肿痛","感染等鉴别、尿酸及必要检查","所有关节疼痛都是痛风"],["痛风不再疼","尿酸趋势、复发、规范随访","鱼油已经解决高尿酸"]]},"bottom_heading":"核查补充：最关键的两个区别","bottom":[{"title":"日常控糖与急救不同","bullets":["减少过量含糖饮料，不能被误用成发生低血糖时也拒绝糖。","NIDDK建议清醒且能吞咽的成人低血糖时摄入15—20克快速糖类，15分钟后复测。","严重意识异常或不能吞咽时不强行喂食，需要立即急救。"]},{"title":"止痛与降尿酸不同","bullets":["NIAMS把缓解急性发作与长期管理高尿酸分为不同目标，往往需要不同治疗。","饮食和生活方式是管理的一部分，不能保证代替需要的降尿酸药物。","给食物或补剂做效果记录时，同时记录检验变化，不只记录关节痛感。"]}],"caution":"课堂“夜间醒来一定是胰岛素抵抗”“低血糖不要吃糖”等表述不能照搬，后者与规范处理相冲突。","sources":["D2-2 02:08:09.010—02:09:46.100","D2-2 02:15:44.150—02:22:45.480","D2-3 00:17:33.810—00:18:12.960"],"number":27,"id":"topic-27","group":2,"references":[{"title":"NIDDK：低血糖","url":"https://www.niddk.nih.gov/health-information/diabetes/overview/preventing-problems/low-blood-glucose-hypoglycemia","supports":"成人低血糖快速糖类处理及复测原则。"},{"title":"NIAMS：痛风诊疗","url":"https://www.niams.nih.gov/health-topics/gout/diagnosis-treatment-and-steps-to-take","supports":"缓解发作和管理高尿酸是不同治疗目标。"}]},{"title":"生物节律、睡眠与月经","subtitle":"先分清时间规律、睡眠中断和伴随的全身问题","core":["昼夜节律接受光照、活动与作息等线索，稳定的生活节奏有助建立观察基础。","入睡时间推迟、整夜失眠、频繁醒来和夜尿，需要分别描述。","月经改变同时涉及内分泌、能量摄入与多种疾病，不能只用节律解释。"],"cards_heading":"将相关内容分成三组","cards":[{"title":"节律：每天的时间线","bullets":["<b>中枢时钟<\/b>：原稿“视上上核”整理为视交叉上核，参与昼夜节律调节。","<b>光照信号<\/b>：课堂强调白天接触自然光，帮助把活动时间与昼夜变化对应起来。","<b>不同信号<\/b>：褪黑素与腺苷不是同一物质，前者涉及节律，后者与睡眠压力有关。","<b>生活记录<\/b>：固定记录起床、光照、运动、咖啡因与入睡时间，比只记睡了几小时更细。"]},{"title":"睡眠：先分表现","bullets":["<b>入睡问题<\/b>：是睡意来得很晚，还是有睡意却睡不着，分别记录。","<b>维持问题<\/b>：夜间醒来需要关注疼痛、呼吸、情绪、药物及其他影响。","<b>代谢关联<\/b>：课堂讨论夜间血糖和夜尿，但不能据此断定所有早醒均由血糖造成。","<b>神经解释<\/b>：大脑、小脑、自主神经的课堂框架是简化模型，不覆盖全部失眠原因。"]},{"title":"月经：独立描述变化","bullets":["<b>周期与经量<\/b>：把周期长短、经量、疼痛和情绪分别记，避免只写“月经不调”。","<b>整体背景<\/b>：营养摄入、体重和压力变化可与月经相关，但不是唯一解释。","<b>课堂辅助<\/b>：讲师提出节律管理及营养支持，部分配方仅指PPT行号，不能复原。","<b>运动联系<\/b>：骨盆稳定训练作为课堂经验保留，不能据此推断痛经由骨盆不稳造成。"]}],"table":{"title":"记录什么，才更容易看出规律","headers":["记录对象","建议分开写","避免混写"],"rows":[["入睡","上床时间、睡意、估计入睡时间","在床时间等于睡眠时间"],["夜醒","次数、时点、伴随症状","所有夜醒都归为低血糖"],["白天状态","困倦、疲劳、午睡、咖啡因","疲劳等于皮质醇耗竭"],["月经","周期、经量、疼痛、用药","所有改变都归为缺维生素"]]},"bottom_heading":"课堂策略与核查补充","bottom":[{"title":"保留可观察的部分","bullets":["尽量稳定起床与就寝安排，并记录白天活动和晚间强光暴露。","课程不主张只靠补剂处理所有睡眠问题，这一点可保留为复习原则。","若症状持续、明显影响白天功能，或月经变化显著，应进一步评估病因。"]},{"title":"核查补充","bullets":["NHLBI将光照与褪黑素列为部分节律障碍的治疗工具，使用时间应因类型而定。","褪黑素不是所有失眠的统一答案，不能照搬固定睡前时点给所有人。","“玻璃完全挡住相关蓝光”“锻炼必须上午完成”等绝对化表述不纳入结论。"]}],"caution":"原稿部分配方依赖未提供的PPT；本页不补猜配方，也不把“皮质醇耗竭”当作已确定诊断。","sources":["D2-2 02:22:45.480—02:39:03.210","D2-3 00:18:12.960—00:18:31.880"],"number":28,"id":"topic-28","group":2,"references":[{"title":"NHLBI：昼夜节律障碍治疗","url":"https://www.nhlbi.nih.gov/health/circadian-rhythm-disorders/treatment","supports":"光照和褪黑素用于特定节律障碍，不能作为所有失眠统一方案。"}]},{"title":"视觉变化与能量支持","subtitle":"区分眼部症状、一般疲劳和课堂中的营养解释","core":["眼酸、看不清、颜色改变和飞蚊属于不同表现，不能都叫视疲劳。","课中把视网膜、眼球运动和能量代谢分别讨论，适合用来整理问题。","症状分类帮助沟通，不能替代眼科检查，也不能据此选择一套补剂。"],"cards_heading":"把“眼睛不舒服”拆开说","cards":[{"title":"先描述看到什么","bullets":["<b>清晰度<\/b>：看远、看近或持续模糊应分开描述，还要记录是否突然发生。","<b>色彩变化<\/b>：左右眼颜色鲜艳程度不同值得记录，但不能直接认定为供血不足。","<b>漂浮黑影<\/b>：飞蚊的数量、出现时间及是否伴闪光，是需要告知医生的信息。","<b>眼酸与干涩<\/b>：与用眼时长、眨眼、环境或屈光问题的关系，需另行观察。"]},{"title":"课堂如何分组","bullets":["<b>视网膜方向<\/b>：课程提到叶黄素、DHA及其他抗氧化成分的相关研究方向。","<b>运动疲劳方向<\/b>：讲师将酸胀等主观感受与眼球活动和能量消耗联系。","<b>产品比较<\/b>：虾青素、硫辛酸等在课中作为补充选择，没有充分材料证明谁更优。","<b>保留限制<\/b>：原稿没有完整疾病分期与适用条件，不整理成通用护眼套餐。"]},{"title":"能量与辅酶Q10","bullets":["<b>课程联系<\/b>：从持续工作的心肌与大脑，联想到细胞能量供给和线粒体。","<b>辅酶概念<\/b>：辅酶Q10参与细胞能量代谢，但生化作用不等于人人需要补充。","<b>衰老讨论<\/b>：讲师提出年龄增长后重视能量支持，属于课程的整体观点。","<b>疲劳个案<\/b>：最后问答中，讲师对“运动后很累、休息就恢复”明确表示信息不足。"]}],"table":{"title":"课堂中的区分与核查边界","headers":["表现或主题","适合留下的学习点","需要避免的推断"],"rows":[["飞蚊","描述黑影、闪光及起病时间","主要由视神经供血不足造成"],["色觉不同","左右眼差异可供医生参考","自行看一张图即可诊断"],["用眼后酸胀","结合屈光、环境与用眼习惯","必然需要某种营养补剂"],["年龄与疲劳","综合看睡眠、活动、疾病和营养","年龄大就必须补辅酶Q10"]]},"bottom_heading":"眼部变化的核查补充","bottom":[{"title":"NEI资料指出","bullets":["飞蚊常与玻璃体随年龄发生的变化有关，并非都来自视神经供血问题。","突然大量新飞蚊、闪光或幕帘样阴影，可能与视网膜裂孔或脱离有关。","出现这些突然变化应立即寻求眼科或急诊评估，不先等补剂见效。"]},{"title":"复习时保留的原则","bullets":["先说清楚症状是什么，再讨论可能来源；不同眼部疾病不能共享同一解释。","区分研究中的特定配方、特定疾病阶段与一般保健宣传。","课堂要求辅酶Q10与维D固定分开服用的理由未充分核实，不设成统一规则。"]}],"caution":"原稿将飞蚊与玻璃体问题过度分离；本页已按NEI资料补充纠正，避免延误眼部急症。","sources":["D2-2 02:43:28.620—02:55:17.510","D2-3 00:19:43.290—00:20:33.210","D2-3 00:21:28.530—00:21:39.290"],"number":29,"id":"topic-29","group":2,"references":[{"title":"NEI：飞蚊","url":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases/floaters","supports":"玻璃体常见原因和突发飞蚊、闪光、幕帘阴影的紧急评估。"}]},{"title":"补剂选择与课程收束","subtitle":"从“买什么”回到目标、来源、证据和实际反应","core":["课程最后再次强调：先理解消化吸收和具体问题，再决定是否需要补充。","不要把所有产品同时加入；目标越模糊，越难判断哪一种带来效果或不适。","抗氧化机制、个人体验和临床获益属于不同证据，不能互相替代。"],"cards_heading":"从最后问答提炼三条主线","cards":[{"title":"先讲清补充目标","bullets":["<b>课程排序<\/b>：讲师将白藜芦醇、姜黄素、鱼油和维D放在不同作用目标下比较。","<b>鱼油标签<\/b>：课堂强调分别查看EPA、DHA含量，不只看“鱼油总重量”。","<b>基础支持<\/b>：铁、镁和B族在课中多次出现，重点仍是需要与缺乏风险。","<b>并非越多越好<\/b>：不能把原稿的个人偏好排名理解成统一推荐或疗效保证。"]},{"title":"产品与植物提取物","bullets":["<b>形式与含量<\/b>：原料名、每份成分、实际用量和复合配方需要分别核对。","<b>植物不是同一种<\/b>：枸杞、黑果枸杞、人参类和南非醉茄不能仅凭俗名互换。","<b>课堂评价<\/b>：银杏与槲皮素的排序多来自讲师个人体验，不代表严谨比较试验。","<b>原料风险<\/b>：课程反对随意购买散装原料自配；剂量、纯度和质量控制都可能不明。"]},{"title":"胃部与基础维生素","bullets":["<b>回到消化<\/b>：课程以卷心菜汁和康复新液讨论胃黏膜，但不能据此判断所有胃病。","<b>名称辨析<\/b>：“维生素U”是历史用语，不等同于已确立的必需维生素。","<b>维生素B1<\/b>：讲师提醒长期大量饮酒者关注营养风险，而非只看抗氧化产品。","<b>维生素C<\/b>：课堂谈到吸烟、感染与维C；不能把水溶性等同于高剂量无风险。"]}],"table":{"title":"课堂提到的类别怎样整理","headers":["类别","课堂关注的用途","笔记保留的边界"],"rows":[["白藜芦醇、姜黄素","抗氧化与抗炎","机制和经验不能证明延缓人体衰老"],["鱼油、EPA与DHA","全身及神经相关支持","看具体成分与适用证据，不无限叠加"],["西洋参、南非醉茄","疲劳和压力体验","考虑疾病、肝功能与药物相互作用"],["胃部辅助产品","胃黏膜相关症状","不替代幽门螺杆菌、溃疡等病因处理"],["B族、维生素C","基础营养支持","也要评估重复摄入、剂量与耐受"]]},"bottom_heading":"留下可继续用的笔记方法","bottom":[{"title":"从目标到复查","bullets":["写下要解决的具体问题、持续时间、可能原因，以及已经做过的检查。","每次改变保留产品、成分与时间记录，观察收益和不适，不靠模糊印象。","无效时回到原先判断，不能只用加量或增加品种来解释失败。"]},{"title":"核查补充","bullets":["NCCIH指出抗氧化补剂的健康获益不能由实验室机制直接推断，部分还可能有害。","南非醉茄存在肝损伤和用药相互作用风险，长期安全性证据有限。","原课“越多越好”“照片看着年轻证明延寿”等说法保留为个人观点，不列入结论。"]}],"caution":"胃部反复不适或警示症状需要病因评估；原稿“任何烂胃都能修好”和高剂量补剂套餐不转成处方。","sources":["D2-2 02:54:03.820—02:59:08.850","D2-3 00:00:00.740—00:00:29.100","D2-3 00:04:12.240—00:17:33.810","D2-3 00:18:31.880—00:21:56.140"],"number":30,"id":"topic-30","group":2,"references":[{"title":"NCCIH：抗氧化补剂","url":"https://www.nccih.nih.gov/health/antioxidant-supplements-what-you-need-to-know","supports":"抗氧化机制不能直接证明人体临床获益，补剂可能有风险。"},{"title":"NCCIH：南非醉茄","url":"https://www.nccih.nih.gov/health/ashwagandha","supports":"长期安全性不确定、肝损伤报告及孕期和甲状腺疾病相关注意。"}]}],"images":[{"number":1,"title":"目录与阅读说明"},{"number":2,"title":"脑营养的整体框架"},{"number":3,"title":"脑肠联系与神经元支持"},{"number":4,"title":"消化从进食前开始"},{"number":5,"title":"嗅觉、记忆与进食"},{"number":6,"title":"胃酸与胃食管反流"},{"number":7,"title":"胃黏膜与消化支持方案"},{"number":8,"title":"胰腺、胆汁与脂肪吸收"},{"number":9,"title":"肝脏功能与体征观察"},{"number":10,"title":"皮肤、抗氧化与补剂索引"},{"number":11,"title":"菌群、纤维与大便观察"},{"number":12,"title":"小肠菌群与菊粉耐受"},{"number":13,"title":"肠屏障与营养支持"},{"number":14,"title":"生食、寄生虫与免疫"},{"number":15,"title":"脑肠轴与迷走神经"},{"number":16,"title":"疼痛、平衡与营养"},{"number":17,"title":"四肢关节与动作控制"},{"number":18,"title":"血脑屏障与脑雾"},{"number":19,"title":"DHA、EPA 与脂肪来源"},{"number":20,"title":"铁、贫血与供氧"},{"number":21,"title":"B12、叶酸与贫血"},{"number":22,"title":"脱发的分类思路"},{"number":23,"title":"免疫、炎症与食物反应"},{"number":24,"title":"甲状腺与全身症状"},{"number":25,"title":"维生素D、K2与镁"},{"number":26,"title":"断食、生酮与自噬"},{"number":27,"title":"血糖、肥胖与尿酸"},{"number":28,"title":"生物节律、睡眠与月经"},{"number":29,"title":"视觉变化与能量支持"},{"number":30,"title":"补剂选择与课程收束"},{"number":31,"title":"核查资料"},{"number":32,"title":"核查资料（续）"},{"number":33,"title":"核查资料（续）"},{"number":34,"title":"核查资料（续）"},{"number":35,"title":"核查资料（续）"},{"number":36,"title":"核查资料（续）"}]};
